import type { Arc } from '../types';
import { arc, battle, beat } from './arc-helpers';

const CREW = ['luffy', 'zoro', 'nami', 'usopp', 'sanji', 'chopper', 'robin', 'franky', 'brook'];

export const newWorldArcs: Arc[] = [
arc({ id: 'fish-man-island', name: 'Fish-Man Island', sagaId: 'fish-man-island', chapters: [603, 653], status: 'complete', premise: 'Ten thousand metres down, a kingdom’s old wounds decide whether a promise to a dead queen can hold.', locationIds: ['fish-man-island', 'ryugu-palace', 'thousand-sunny'], characterIds: [...CREW, 'jinbe'], overview: [
  'Two years after Marineford, the reunited crew coats the Sunny and sinks beneath the Red Line. The descent is its own adventure: a Kraken to tame, deep trenches full of hostile life, and Caribou stowed away in a barrel. But the island waiting at the bottom carries older damage than any single voyage. Fish-Man Island lies directly beneath Mary Geoise, its people subjected for centuries to slavery and contempt from the surface, and the memory of Arlong Park now reads as one small outbreak of a far wider resentment.',
  'The arc sets two responses to that history against each other. Queen Otohime spent her life gathering signatures for a peaceful migration to the surface, insisting that hatred taught to children would outlast any single injustice. Hody Jones absorbed the opposite lesson and now leads the New Fish-Man Pirates in a coup meant to punish humans and the royal family that tolerated them. Luffy arrives as neither saviour nor diplomat. A fortune-teller has seen him destroying the island, and for much of the story the prophecy seems more plausible than any rescue.',
  'What follows is the crew’s first full demonstration of what the two years apart produced. Every member takes the field at Gyoncorde Plaza with skills that finally match their ambitions, and Luffy’s decision to stop Noah rather than simply defeat Hody shows a captain thinking about consequences. The banquet afterwards is joyful, but the arc closes on a warning: Big Mom protects this island in exchange for sweets, and Luffy has just told her that he will take it from her.',
], beats: [
  beat('descent', 'Ten thousand metres down', '603–609', [
    'Coated in a bubble by Rayleigh’s technique, the Sunny drops through the shallows into a sea that stops resembling the ocean the crew knew. The reunion is hardly settled before a Kraken attacks. Luffy insists on taming rather than killing it, and the creature he names Surume becomes their escort through the trenches. Caribou, discovered hiding in a barrel, is kept aboard as a nuisance rather than thrown overboard, which will matter later when his eavesdropping carries news of the island outward.',
    'The deeper layers bring underwater volcanoes, fish that could crush a ship, and a brief encounter with Vander Decken IX, whose hurled weapons keep seeking the mermaid princess. The crew is scattered on arrival, and the island reveals itself as a bubble-domed paradise lit from within. Camie, Hatchan and Pappag reappear as guides, and the Mermaid Cafe’s owner Shyarly reads her crystal ball. What she sees is Straw Hat Luffy destroying Fish-Man Island, and the vision spreads through the streets faster than the crew can.',
  ]),
  beat('the-palace-and-the-princess', 'Ryugu Palace and the girl in the tower', '610–615', [
    'Neptune’s soldiers arrest the crew almost at once, but the king himself receives Luffy at Ryugu Palace out of respect for Jinbe’s letter. Luffy wanders off in search of food and stumbles into Hard-Shell Tower, where Princess Shirahoshi has lived for ten years because Vander Decken’s ability lets his thrown weapons follow whomever he has touched. She is enormous, gentle and prone to tears. Luffy bullies her out of self-pity, breaks an axe that comes hurtling through the wall, and offers to take her outside for a walk.',
    'The walk is to the Sea Forest, where her mother is buried, and it is smuggled past the guards inside the mouth of the shark Megalo. Behind them the palace is already failing. Vander Decken has come in person for the princess he swears to marry or kill, and Hody Jones arrives at the same gate with an army that has been drilling for this day for years. Zoro, Usopp, Brook and Nami, left behind with a king they were supposed to be robbing, find themselves the only defence Ryugu Palace has.',
  ]),
  beat('hodys-coup', 'The palace floods', '613–620', [
    'Hody opens the palace gates to the sea and lets the water do his work. His officers swallow Energy Steroids by the handful, and their bodies swell with a strength that will cost them years. Zoro meets Hody on the drowning floor and cuts him deep enough to matter, but a fish-man in water is a different animal, and once the hall is submerged the crew’s advantage is gone. Neptune is chained. Hody announces to the whole island that the royal family will be executed in Gyoncorde Plaza, and that the humans who came with Jinbe’s blessing will die beside them.',
    'Luffy reaches the Sea Forest with Shirahoshi, Vander Decken’s arrows still hunting her, and finds Jinbe waiting under the hull of a ship the size of a town. Noah has lain here for centuries, kept by royal decree for a promise nobody alive can explain. Jinbe asks Luffy not to fight Hody: a human beating a fish-man revolution would only feed the story Hody tells. Luffy refuses, the two square off, and it takes Nami, who has more reason than anyone to hate fish-men, to settle the argument by asking to hear the truth about Arlong.',
    'Hody, meanwhile, tells Neptune what only Shirahoshi knew. It was he who put the bullet in Queen Otohime and framed a human for it, and the princess has carried his secret for ten years because her mother asked that nobody be hated on her account. Hody says it as a boast, then explains what he is: a fish-man who was never enslaved and never struck by a human, who learned his hatred from other fish-men and calls it justice. Jinbe, listening from the forest, begins the story the crew needs to understand what they are about to fight.',
  ]),
  beat('otohime-and-tiger', 'The queen who gathered signatures', '621–627', [
    'Sixteen years earlier, Fisher Tiger climbed the Red Line and freed the slaves of Mary Geoise, humans and fish-men alike, then formed the Sun Pirates whose brand covered the mark of slavery. He forbade his crew from killing humans, yet he could not stop hating them. When he returned Koala, a freed child, to her village, the Marines were waiting; dying, he refused a transfusion of human blood. His last conversation with Arlong and Jinbe holds both his despair and his instruction not to pass the hatred on.',
    'Otohime spent the same years walking the streets asking her people to sign a petition for migration to the surface. Her Observation Haki let her feel the fear and resentment around her, and she argued that hating an entire species would only reproduce what fish-men had suffered. A Celestial Dragon’s unexpected act of gratitude finally made the petition credible, but she was assassinated soon after. Hody planted the evidence blaming a human, and Shirahoshi, who saw the truth, kept silent to honour her mother’s wish that no one be hated for it.',
    'The Sun Pirates broke apart along the fault Tiger’s death exposed. Arlong went to the East Blue to build a kingdom of fish-men on top of humans; Jinbe accepted a Warlord’s seat to keep the island under the Government’s protection and spent years unable to say why the cost was worth paying. Both men learned from the same corpse. The flashback closes on the children who watched Otohime’s funeral, Hody among them, and on the signatures she collected, burned in the chaos the night she died.',
  ], 'flashback'),
  beat('gyoncorde-plaza', 'Ten against a hundred thousand', '628–635', [
    'Hody drags Neptune and the princes to Gyoncorde Plaza and stages a public execution to make his revolution visible. He has a hundred thousand fighters, the king in chains, and an audience of citizens who have not yet decided whether to cheer. Shirahoshi is lured out by a threat to her father and delivered straight into his hands. The Straw Hats interrupt with a coordinated entrance from beneath the plaza, Luffy striding out of Megalo’s mouth, and his Conqueror’s Haki drops half the army before a blow is thrown.',
    'What follows is the crew’s first joint fight in two years, and it is a display. Zoro’s cutting range takes the octopus swordsman Hyouzou, Sanji’s aerial kicks answer the giant Wadatsumi, Franky’s new machines and Usopp’s weaponised plants clear whole ranks. Chopper controls a Monster Point he could once only survive, Robin’s enlarged limbs crush Hammond, Brook leaves his body to walk through Zeo, and Nami’s weather locks enemies in place while she frees Neptune. Each of them announces, without saying so, that the two years were not wasted.',
  ]),
  beat('noah', 'The ark that fell from the sky', '636–647', [
    'Vander Decken, spurned by Shirahoshi one last time, throws the only thing large enough to make his point: Noah itself, dragged from the Sea Forest and hurled at the island from above. The falling ark is a threat no single victory can address. Hody, seeing his revolution about to be flattened with the city, decides the ship is a gift and rides it down, stabbing Decken to keep it falling. Shirahoshi swims up to draw it away from her people, and Luffy follows her into open water where a fish-man holds every advantage.',
    'The duel beneath Noah is fought in Hody’s element and on Luffy’s terms. Jinbe reads the currents, Fukaboshi carries Luffy into range, and each punch that lands on Hody costs Luffy blood from the wound the trident left. When Hody finally breaks, Luffy turns his fists on the ark and begins to tear through it, exactly as Shyarly foresaw. Then the Sea Kings come. Shirahoshi’s cry has summoned them, they take Noah’s weight in their mouths, and their voices name her the Ancient Weapon Poseidon.',
    'Luffy stops. With the island safe, he holds back the blow that would have finished the ship, and the crowd that was ready to hate him watches a human choose not to destroy their kingdom. The prophecy has come true and been refused in the same gesture. Hody’s officers, hauled out of the water, are already ageing before anyone’s eyes as the steroids exact their price. Luffy collapses on the plaza stones, bled white, and the fish-men who feared him are the ones who run for a doctor.',
  ]),
  beat('blood-and-a-declaration', 'A transfusion and a challenge', '648–653', [
    'Luffy collapses from blood loss, and Jinbe donates his own, an act the island’s law once forbade and which Fisher Tiger refused from the other direction. The gesture completes the argument the flashback began. At the palace banquet Neptune reveals the island’s Poneglyph, which Robin reads: it contains Joy Boy’s apology to the mermaid princess of his era, alongside a promise about Noah that Neptune insists must be honoured by a generation still to come.',
    'The celebration is interrupted by a call from the surface. Big Mom protects the island in exchange for candy, and the New Fish-Man Pirates destroyed the factory that makes it. Luffy takes responsibility on the phone and declares that he will find her in the New World and take Fish-Man Island as his own territory. Jinbe declines to join yet, owing Big Mom a formal severance, but promises to return, and the Sunny rises toward the New World with a treasure chest quietly sent on ahead.',
  ]),
], battles: [
  battle('zoro-hody', 'Zoro versus Hody Jones in the flooded palace', '613–617', 'Hold Ryugu Palace against a coup while the room fills with water and the king stands in chains.', 'Zoro meets Hody in the throne room before the sea comes in and cuts him badly enough that the fish-man reaches for the first of many pills. Then Hody opens the gates, the hall floods, and a swordsman who cannot breathe water is fighting a shark in its own element. Usopp and Brook drag him toward the last pocket of air.', 'The crew is captured with Neptune and only escapes because Hody wants an audience for the execution. Hody carries a wound that his steroids cannot close, and Zoro knows exactly how much stronger the drugs have made his enemy.', ['A blade drawn in a throne room', 'The gates open to the sea', 'Pills swallowed by the handful', 'Chains for a king']),
  battle('crew-vs-new-fish-man-pirates', 'The Straw Hats versus the New Fish-Man Pirates', '634–641', 'Break an army of a hundred thousand with nine people, in front of a nation deciding whether to fear them.', 'Luffy’s Conqueror’s Haki takes fifty thousand fighters out of the fight in one breath. The officers who remain are matched one by one: Hyouzou’s swords against Zoro, Wadatsumi’s bulk against Sanji and Jinbe, Ikaros Much against Franky’s tanks, Daruma against Usopp’s seeds, Dosun against a Chopper who has learned to steer his monster, Zeo against a skeleton he cannot hit, Hammond against a woman with a thousand arms.', 'The officers fall and Neptune is freed by Nami’s hand. The citizens watching from the plaza edges have seen humans fight for them, and the island’s verdict on the crew begins to shift before the ark ever falls.', ['Half an army drops unconscious', 'Three swords against eight', 'A skeleton steps out of his skin', 'Nami turns the key in the chains']),
  battle('luffy-hody', 'Luffy versus Hody Jones · the falling Noah', '634–647', 'Stop a coup led by a man who has decided that his hatred is his inheritance, and keep a city-sized ark from crushing the island.', 'Hody’s doses of Energy Steroids make him stronger and less human with each swallow. Luffy fights him in the plaza, then in open water beneath Noah, where a fish-man should hold every advantage. Jinbe reads the current, Fukaboshi carries him into range, and Luffy’s Red Hawk and Gear Third punch through the ark while Shirahoshi’s Sea Kings close in.', 'Hody is smashed through the hull of Noah and falls. His officers age catastrophically in prison as the steroids exact their price, and Neptune’s people see the surface pirate they feared halt his assault the moment the island is safe.', ['The plaza falls silent', 'A trident through the shoulder', 'An ark descends from above', 'A punch inside the sea', 'The Sea Kings arrive', 'A fist that stops']),
], legacy: [
  'The Poneglyph and Shirahoshi’s identity give the crew its first direct encounter with an Ancient Weapon, and Joy Boy’s name enters the story as a person who failed a promise rather than a myth. Neptune’s insistence that Noah be preserved for a future task, and Luffy’s willingness to stop hitting it, establish that the Void Century has obligations attached to it. Robin reads the stone with a new sense that history is asking something of the present rather than simply recording the past.',
  'Jinbe’s deferred recruitment and Luffy’s telephone declaration to Big Mom shape the whole New World route. Fish-Man Island is now a place Luffy has claimed out loud, and the Emperor who protected it will remember. Caribou leaves carrying knowledge of Shirahoshi that will find its way to ears in the New World. The island’s decision to celebrate a human pirate, after Otohime’s murder had been blamed on one, marks the first real movement toward the queen’s dream of coexistence.',
] }),

arc({ id: 'punk-hazard', name: 'Punk Hazard', sagaId: 'dressrosa', chapters: [654, 699], status: 'complete', premise: 'An island half frozen, half burning hides a chemist, stolen children, and an alliance aimed at an Emperor.', locationIds: ['punk-hazard', 'thousand-sunny'], characterIds: CREW, overview: [
  'The New World announces itself with a distress call from an island the Marines list as uninhabitable. Punk Hazard was destroyed twice: by Vegapunk’s abandoned experiments and by a duel between Akainu and Aokiji that left one side permanently burning and the other frozen solid. The Straw Hats split across both halves and find a research facility still operating, populated by centaurs, a talking severed head, and children too large for their ages who beg the crew to take them home.',
  'Trafalgar Law is waiting there as a Warlord and as something else. His proposal, a pirate alliance to bring down Kaido by cutting off the artificial Devil Fruit trade that Doflamingo supplies, changes the scale of the crew’s ambition from surviving the sea to dismantling a specific Emperor’s power. Luffy accepts in the time it takes to grin. Smoker and Tashigi, chasing the same call, discover that the corruption they hunt sits inside their own chain of command.',
  'Caesar Clown, the scientist whose gas weapon killed the island, is the arc’s villain but not its centre. The children he has been dosing and the cloud of petrifying poison rolling across the ice are what force pirates, Marines and samurai to run in the same direction. By the end, an alliance exists, a Warlord’s underground network has been exposed to the wrong witnesses, and Doflamingo has personally taken notice of a crew that has only just returned to the newspapers.',
], beats: [
  beat('fire-and-ice', 'The island cut in two', '654–660', [
    'A voice on a Den Den Mushi begs for rescue from an island the Sunny’s Log Pose says is dead. The needle points three ways for the first time, and Luffy chooses the one that shakes. He, Zoro, Usopp and Robin cross a shoreline of fire and meet centaurs who should not exist and a dragon with a pair of human legs protruding from its body. They kill the dragon, eat it, and use the legs, which turn out to belong to someone who is still talking, as a guide.',
    'Aboard the Sunny, the others are gassed and wake in a laboratory. Nami, Sanji, Franky and Chopper find children in hospital gowns who are far too large for their ages, a room the staff call the Biscuits Room, and a doctor who wants them back. They break out with the children onto the frozen half of the island, into snow that buries the ruins of a research station nobody is supposed to be operating. Brownbeard, a former pirate who now serves as the laboratory’s centaur guard, blocks the way with a rifle and a grudge.',
  ]),
  beat('law-and-smoker', 'A surgeon takes a heart', '660–664', [
    'The severed head belongs to Kin’emon, a samurai from Wano who arrived searching for his son and was cut into pieces that still move. He is hostile to pirates on principle and politely grateful to these ones. Smoker’s G-5 unit arrives on the same distress signal, and at the laboratory door they meet Trafalgar Law, who has held a Warlord’s title since Marineford and does not explain why he is here. He asks the Marines to leave. Smoker, who has spent two years disbelieving official stories, declines.',
    'Their duel is short and instructive: a Vice Admiral of smoke against a surgeon who can rearrange whatever lies inside his sphere. Law cuts Tashigi in half without killing her, then reaches into Smoker and takes his heart out as a paperweight. Before that, in a spare moment, he has already swapped Nami, Sanji, Franky and Chopper into one another’s bodies, so that a cook is now a navigator and a reindeer is inside a cyborg. The Straw Hats hold one another’s skins and look for the man who did it.',
  ]),
  beat('the-alliance', 'A surgeon proposes a war', '665–671', [
    'Caesar Clown, a scientist wanted for the gas experiment that killed Punk Hazard, runs the laboratory under Doflamingo’s protection. He treats the children as materials, feeding them a drug that ruins their judgement while the promised cure keeps them obedient. The Yeti Cool Brothers, two giants with rifles, attack out of the snow and carry Nami off in Franky’s body; Franky, in Chopper’s, pilots his own enormous robot with more enthusiasm than judgement. Law arrives to retrieve the hostage and, over the wreckage, makes Luffy an offer.',
    'Law explains the shape of the world beyond. Doflamingo trades SMILE, an artificial Devil Fruit, to Kaido, and the substance Caesar manufactures here, SAD, is the ingredient that makes it possible. Cut the supply, and the Emperor loses the army he is building. Law asks for an alliance to bring Kaido down. Luffy accepts without consulting anyone, which the crew treats as typical rather than alarming. The plan is simple: capture Caesar, expose the poison, and rescue the children before Doflamingo learns of it.',
    'Kin’emon, reassembled, reveals the ability that lets him dress people in imaginary clothes and reveals his purpose: his son Momonosuke was taken to this island. Inside the laboratory, the mystery of how Caesar has operated unchecked answers itself. Vergo, the Vice Admiral who commands Smoker’s own G-5 base, walks into the facility as Doflamingo’s man, placed inside the Marines as a boy and risen to the rank that let him bury every report. Law knows him. He has known him since Minion Island.',
  ]),
  beat('the-children', 'Candy, a small dragon, and a girl who swallows it all', '672–688', [
    'Momonosuke is found in a garbage chute as a small dragon with a boy’s voice, changed by a failed artificial fruit he ate out of hunger. He is Kin’emon’s son, and the samurai will not learn it for hours. Chopper meanwhile struggles to keep the drugged children from running back to their captor, because the drug Caesar feeds them makes withdrawal a physical agony and the candy that relieves it is the only thing they can think about. Caesar broadcasts the laboratory to the underworld’s buyers as a demonstration of his weapon.',
    'When the children break loose and stampede for the candy, the oldest girl, Mocha, grabs the whole supply and runs. Cornered by the friends she is trying to save, she swallows every piece herself rather than let them have it, and Chopper carries her overdosed body through a room full of children trying to kill her. Law’s ability turns the candy into a cure the moment he learns what it is. Zoro and Tashigi face Monet, Caesar’s harpy-winged assistant, and Zoro ends it with a cut that does not need to touch her to make her drop.',
  ]),
  beat('shinokuni', 'The land of the dead', '676–690', [
    'Caesar unleashes his experimental weapon Shinokuni, a gas that petrifies everything it touches, and the cloud advances across the island, forcing enemies onto the same path toward the laboratory. G-5 Marines who spent the day trying to arrest pirates are now running beside them. Luffy fights Caesar in the corridors and finds that the Gas-Gas Fruit turns a body into something his fists pass through. Caesar, who has never fought without a hostage, keeps a room of children and a switch within reach.',
    'Smoker meets Vergo in the SAD tank room, and the fight is short. Vergo’s full-body Armament Haki is a wall, and a Vice Admiral fighting another Vice Admiral learns that the man was always the stronger of the two. But Smoker has one job. Before he falls he wrenches Law’s heart from Vergo’s grip and returns it, so that when Law walks into the room he is whole for the first time since Smoker took the field. Law dismantles Vergo in a single motion and, with the same cut, opens the SAD tanks that sustain Kaido’s army.',
  ]),
  beat('luffy-vs-caesar', 'The chemist’s own creation', '691–695', [
    'Caesar reveals that he engineered the original disaster four years earlier and blamed it on Vegapunk. When his subordinates realise that he means to let them die in his gas to protect his escape, the laboratory turns against him; the men who dosed the children help the children run. Luffy, who has learned to grab a gas body through Haki, chases Caesar into the open, and his final punch sends the chemist through walls and into the snow. Doflamingo’s voice comes through a Den Den Mushi, cold and amused, and asks Law what he wants.',
    'Law’s answer is the deal he came to make: resign your Warlord title by morning or lose Caesar, and with him the whole SMILE trade. Doflamingo tells Law that he has broken something he cannot repair and hangs up. In the collapsing tank room Vergo, split and dying, refuses to leave his employer’s business unfinished and is buried with it. The gas is at the laboratory doors, and the only way out is a rail line whose car was built for freight.',
  ]),
  beat('the-escape', 'A rail car and a warning', '696–699', [
    'The alliance escapes the gas aboard a rail car with the children, the G-5 Marines, Brownbeard, and the samurai, while the petrified statues of Caesar’s men line the platform behind them. Smoker chooses to let the pirates go, a decision that costs his loyalty nothing and his career something, and Tashigi lets the children ride with the men who saved them. The G-5 Marines, who have spent two years despising pirates, share their coats with the ones on the car.',
    'Aboard the Sunny, Luffy toasts a new friendship with Law, who cannot understand why an alliance keeps turning into a party. Kin’emon and Momonosuke join for the voyage. Zoro and Sanji dispute who deserves credit for outrunning the gas. The morning paper announces that Doflamingo has resigned from the Seven Warlords and abandoned the kingdom of Dressrosa, exactly as demanded, and Law senses the trap even as he sets course for the island where he grew up.',
  ]),
], battles: [
  battle('law-smoker', 'Law versus Smoker at the laboratory door', '661–663', 'Keep the Marines away from a laboratory whose secrets would end a Warlord’s cover and a Vice Admiral’s career.', 'Smoker refuses to leave a crime scene on a Warlord’s word, and Law draws his sphere over the snow. Smoke passes through blades and blades pass through smoke, until Law rearranges the ground under Smoker’s feet. Tashigi is cut in two and left alive; Smoker is opened and closed with his heart in another man’s hand.', 'Law walks back into the laboratory with the Vice Admiral’s heart in a box, having fought a Marine to a standstill without revealing which side he is on. Smoker understands only that the Government he serves has something on this island worth a Warlord’s protection.', ['Snow, smoke and a sphere', 'A swordswoman cut and standing', 'A heart lifted out', 'The door closes on G-5']),
  battle('zoro-monet', 'Zoro and Tashigi versus Monet', '684–687', 'Clear the path to the laboratory while a harpy holds the corridor and the gas eats the building behind them.', 'Monet fights with snow and a smile, burying the corridor and trying to freeze Zoro from the inside. Tashigi insists on the fight and is nearly killed for it; Zoro, who has spent two years learning to cut only what he means to, lets the fear of a stroke do the work a stroke would have done.', 'Monet drops without a wound she can find. Zoro’s cut, aimed at her spirit, leaves her alive and unable to stand, and Tashigi finishes the job with the blade he refused to use.', ['Snow fills a corridor', 'A wing brushes a sword', 'Fear does the cutting', 'Tashigi takes the last blow']),
  battle('caesar-vergo', 'Luffy versus Caesar Clown · Law and Smoker versus Vergo', '680–694', 'Take Caesar alive to expose the SMILE trade, and survive a Vice Admiral whose loyalty to Doflamingo is older than his Marine rank.', 'Caesar’s gas body renders Luffy’s fists useless until Luffy learns to grab him through Haki. Smoker fights Vergo and loses, but not before wrenching Law’s own heart from his opponent’s grip and returning it. Whole again, Law splits the Vice Admiral in the same motion that severs the SAD supply.', 'Caesar is captured and used as the bargaining chip against Doflamingo. Vergo dies in the collapsing laboratory, refusing to abandon his employer, and Smoker leaves Punk Hazard knowing the Marines were infiltrated years ago.', ['Gas takes a human shape', 'A heart changes hands', 'Two halves of a Vice Admiral', 'The tanks bleed out', 'A chemist through the wall', 'The rail car outruns the cloud']),
], legacy: [
  'The Straw Hat and Heart Pirates alliance is the first time Luffy commits to a target rather than a horizon. Kaido, previously a name, becomes the endpoint of a plan, and Kin’emon and Momonosuke carry the first threads of Wano into the crew. The Marines’ own corruption, exposed to G-5 rather than to the reader alone, cracks the trust Smoker and Tashigi had left in their chain of command and shows an institution compromised long before the story reached the New World.',
  'Caesar Clown becomes a portable hostage whose value every faction understands, and Doflamingo’s ostentatious resignation, announced in the same newspaper that shows him leaving, introduces a manipulator who plays the world press as skilfully as he plays his opponents. Law’s history with the Donquixote family, still unspoken, hangs over the course he sets for Dressrosa, where a personal debt and a political scheme are about to meet on the same island.',
] }),

arc({ id: 'dressrosa', name: 'Dressrosa', sagaId: 'dressrosa', chapters: [700, 801], status: 'complete', premise: 'A kingdom of toys and roses hides ten years of erased people and the debt Law came to collect.', locationIds: ['dressrosa', 'green-bit', 'thousand-sunny'], characterIds: ['luffy', 'zoro', 'usopp', 'robin', 'franky'], overview: [
  'Dressrosa is a country designed to be admired. Dancers, gladiators and living toys fill its streets, and its king, the former Warlord Donquixote Doflamingo, is loved with a fervour that seems hard to fake. The Straw Hats arrive on a bargain: Caesar Clown returned in exchange for a resignation the newspapers reported and the world believed. Luffy meanwhile heads for the Corrida Colosseum, where the prize is the Flame-Flame Fruit that once belonged to his brother.',
  'Beneath the spectacle lies a mechanism built on a single Devil Fruit. Sugar’s power turns people into toys and erases them from every memory, so the kingdom can lose a rebel, a father or a former king overnight and celebrate the next morning. Ten years earlier Doflamingo used that trick and a staged massacre to take the throne from King Riku. The toy soldier who guides Usopp and Franky through the underground is one of the erased.',
  'The arc grows into the longest campaign the crew had yet fought, joined by colosseum rivals, dwarves, a Revolutionary, a Marine Admiral who gambles on his conscience, and a surgeon fighting the man who murdered his mentor. When Doflamingo drops the Birdcage over the country, the fight becomes a countdown. Its resolution creates a fleet Luffy did not ask for and a bounty that marks him as a problem no Warlord can solve.',
], beats: [
  beat('the-colosseum', 'Lucy enters the Corrida Colosseum', '700–716', [
    'The alliance splits three ways. Sanji, Kin’emon and Franky head into town, Nami’s group guards the ship and Caesar, and Luffy, disguised as the gladiator Lucy, enters the Corrida Colosseum when he learns that Ace’s Flame-Flame Fruit is the prize. In the waiting room he meets Bartolomeo, a fan who worships him; Cavendish, a swordsman who resents him; Rebecca, a gladiator the crowd despises; and Don Chinjao, who wants him dead over a grudge against his grandfather. A one-legged toy soldier befriends Franky and reveals that toys in Dressrosa are not what they seem.',
    'Law goes to Green Bit to hand over Caesar and finds Admiral Fujitora waiting, with the exchange revealed as fiction: Doflamingo never resigned, and the newspaper report was a manipulation of the World Government itself. Robin and Usopp fall into the Tontatta kingdom of dwarves beneath Green Bit, where the tiny people believe Usopp is a hero descended from the legendary Noland, and Usopp does nothing to correct them. Sanji, in the town, is drawn to the dancer Violet and betrayed by her before she changes her mind.',
    'In the arena the blocks are fought out in a ring surrounded by water full of fighting fish. Bartolomeo wins Block B by standing behind a barrier no one can pass; Cavendish wins Block D by doing nothing at all until Rebecca outlasts everyone else in her own block and takes it instead. Luffy defeats Chinjao in Block C, and the old pirate weeps when a punch restores the drill-shaped point of his head that Garp once flattened. Above the crowd, Doflamingo watches Lucy fight and knows exactly who is under the mask.',
  ]),
  beat('the-erased', 'The kingdom that forgot its own people', '717–728', [
    'The toy soldier tells the history that Dressrosa cannot remember. Ten years earlier Doflamingo manipulated King Riku into appearing to slaughter his own citizens, controlling the king’s body with his strings while the palace guard burned the streets, then arrived as the saviour who ended the madness. Sugar’s Devil Fruit made the leftover witnesses into toys and erased them from memory, so wives forgot husbands and daughters forgot fathers. A contract in the toy’s heart forbids them from telling anyone what they used to be.',
    'The soldier has built a resistance in the underground trade port, where the Donquixote Family runs an armoury and where dwarves have been enslaved to make the SMILE factory work. His plan is a single act: knock Sugar unconscious, and every toy in the country reverts and remembers. Usopp is recruited as a hero he has no intention of being and Franky as a battering ram he is glad to be. Kin’emon finds Kanjuro, his comrade, imprisoned as a toy, and the two men argue over who should have rescued whom.',
    'Rebecca fights in the Colosseum for a fruit she hopes will let her kill the king who murdered her mother, and the toy soldier who trained her cannot tell her that he is her father, Kyros, the greatest gladiator Dressrosa ever had. The crowd calls her the daughter of a murderer because that is what the country remembers of King Riku. Luffy, hearing all of it, promises the soldier that they will win, which the soldier has heard before from men who are now toys.',
  ]),
  beat('laws-fall', 'A surgeon loses twice', '728–731', [
    'Law confronts Doflamingo at the palace with the man’s own strategy in mind and finds himself outmanoeuvred anyway. Doflamingo has arranged for Fujitora to join the fight, and gravity that pins a man to the earth is not something the Op-Op Fruit can cut. Law is shot, then shot again, then chained with sea-stone and told he will be delivered to Green Bit for whatever the Admiral decides. Doflamingo speaks of Corazon while he does it, and Law learns that the man knows exactly how much the name still costs him.',
    'On the Sunny, Doflamingo appears in the sky above the ship and attacks. Sanji holds him for a moment, long enough to see how wide the gap is, and Law’s teleportation, spent from his cell, throws the ship out of range. Nami, Chopper, Brook and Momonosuke flee toward Zou with a Big Mom vessel on their heels and Caesar still aboard as luggage. Kin’emon and Sanji fall back into the town. The alliance that came to trade a hostage has lost its surgeon, its ship and its exit in a single afternoon.',
  ]),
  beat('sugar', 'A hero’s face', '732–743', [
    'Underground, the dwarves’ plan against Sugar depends on a chilli-laced grape and a hero who will not run. Usopp runs. When the first attempt collapses and the dwarves are captured, he abandons them in terror, then turns back, because a lie about being a hero is the only thing keeping a whole nation of tiny people fighting. Trebol catches him and burns him, and drags him before the girl who runs the kingdom as a toy factory, a child who has not aged in ten years because her fruit froze her.',
    'Sugar forces the grape into Usopp’s mouth as punishment. What happens to his face when the spice hits, an involuntary, grotesque mask of pure agony, is so terrifying that the girl faints from the sight of it. Every toy in Dressrosa becomes a person again in the same instant, and every memory that was taken returns to the people who lost it. Mothers remember sons; the country remembers its king. The toy soldier stands up in his own flesh, and Rebecca, in the arena above, feels the name Kyros return to her like a dropped word.',
    'Kyros walks into the palace and takes off Doflamingo’s head, which turns out to belong to a body double. The real Warlord has been elsewhere, watching, and he emerges into a country that has just, all at once, recalled what he did. The freed toys and the dwarves declare Usopp their god. Usopp, half dead in the trade port, accepts the title because there is nobody else to do it.',
  ]),
  beat('sabo-returns', 'The brother from Dawn Island', '744–752', [
    'The masked gladiator who won the Flame-Flame Fruit removes his mask in the arena. He is Sabo, the boy Luffy and Ace swore brotherhood with in Goa, believed dead since a Celestial Dragon’s ship fired on his boat when he was ten. He lived, lost his memory, and recovered it only when Ace’s death was reported. Now the Revolutionary Army’s chief of staff, he has come to Dressrosa to claim what his brother left and to make sure nobody else does. He eats the fruit and lights his fist.',
    'Luffy and Sabo meet on the palace approaches, and Luffy weeps without dignity. Sabo apologises for arriving too late for Ace and promises never to be late again. Then he goes back to the Colosseum to hold the ground against the Blackbeard Pirate Burgess, who wanted the fruit for his own captain, and against Fujitora, who tests the new fire with gravity and finds it holds. Koala and the Revolutionary Army have been in Dressrosa the whole time, tracing the weapons trade that the Colosseum was built to hide.',
  ]),
  beat('the-birdcage', 'Doflamingo closes the country', '745–760', [
    'The freed toys remember everything, and Dressrosa turns against its king in an afternoon. Doflamingo answers by dropping the Birdcage: a dome of razor string that seals the country and shrinks inward. He cuts the Den Den Mushi lines, announces bounties on Luffy, Law, Usopp and the people who defied him, and offers the population a way out by killing one another. King Riku, stumbling out of the arena in the body of a toy no longer, speaks to his people for the first time in ten years and begs them to hold.',
    'Luffy, Zoro and Law climb toward the palace as Pica turns the stone of the island into his body. Colosseum fighters who came for the fruit choose to protect a country they barely know, and Rebecca, Kyros and Viola become the centre of the resistance. Fujitora sides with neither the Warlord nor the pirates, and holds a falling shower of rubble in the sky over the citizens. Bellamy, who once knelt to this king, is turned into a puppet against the man he came to respect, and Luffy has to fight a friend who is begging him not to hold back.',
    'In the trade port Usopp, carried on the shoulders of the dwarves, sees what nobody else can: Sugar, awake again, about to turn the whole resistance back into toys with a single touch. Something opens behind his eyes, a sight that shows him the girl’s aura across a mile of stone, and he fires. The shot lands. Sugar falls again, and the Observation Haki that Usopp did not know he possessed becomes the difference between a kingdom and a toy box. Luffy meanwhile leaves Law chained on the plateau and climbs.',
  ]),
  beat('corazon', 'The boy from the white town', '761–768', [
    'Law was born in Flevance, a city poisoned by the amber lead its people mined without knowing it killed slowly across generations. The world let the city be exterminated to contain a disease it had already misunderstood, and Law escaped carrying the illness and three years to live. He joined the Donquixote Pirates to destroy as much as he could before dying. There he met Rosinante, Doflamingo’s younger brother, a silent man who threw him out of windows and was secretly a Marine officer.',
    'Doflamingo was born a Celestial Dragon and lost that status when his father chose to live among ordinary people, whose hatred nearly killed the family. He shot his own father in the hope of being readmitted and was refused. Rosinante, called Corazon, stole the Op-Op Fruit for Law rather than let his brother sell it, then was executed by Doflamingo on Minion Island while Law hid in a chest inside a field of his silence. Law inherited his life, his hat, and a promise to make the death matter.',
  ], 'flashback'),
  beat('the-royal-plateau', 'Every ally buys a step', '769–783', [
    'The battles on the way to Doflamingo belong mostly to people who were strangers a day before. Sai fights and unexpectedly courts Baby 5; Cavendish’s sleeping self Hakuba cuts through Gladius; Bartolomeo’s barriers protect people he cannot stop insulting; and the dwarves’ commander Leo confronts the executives who tricked his people. Kyros faces Diamante, the man who killed his wife Scarlett, and Rebecca refuses to be a spectator in the fight that decides her father’s honour.',
    'Zoro beats Pica by forcing the giant stone body down to a single, cuttable core, and Franky wears down Senor Pink in a fight the crowd cheers as a contest of manliness. On the plateau, Law confronts Doflamingo with the surgeon’s ability he was given and the Gamma Knife it was meant for, and loses again. Luffy reaches the palace at last, and the Birdcage begins to shrink faster, turning every remaining battle into a race against the wire.',
  ]),
  beat('gear-fourth-and-a-fleet', 'A fourth gear and ten minutes', '784–790', [
    'Luffy abandons restraint and unveils Gear Fourth, a technique that combines inflated muscle with Armament Haki and lets him bounce, hover and hit harder than anything Doflamingo has faced. For the first time the Warlord is knocked out of the sky and through the city he built. But the form has a time limit, and when it runs out Luffy is a boy who cannot use Haki for ten minutes, and the island must survive that long with the cage closing in.',
    'Gatz, the colosseum announcer, becomes the voice of a country counting down. Cavendish and Bartolomeo carry Luffy, Zoro and the gladiators push at the wire with their bodies, and Doflamingo strings a girl to kill her father: Rebecca, controlled, is aimed at Kyros. Viola’s eyes find the strings, Law spends his last strength to move Rebecca out of the fight, and when the minutes are up Luffy rises with a punch the size of the plateau. King Kong Gun sends the king of Dressrosa into the earth, and the Birdcage dissolves over a country that has spent the day learning the truth.',
  ]),
  beat('the-grand-fleet', 'A fleet that chose itself', '791–801', [
    'Fujitora kneels to King Riku to apologise for the Government’s neglect, in front of the citizens, and leaves the question of Luffy’s arrest to a throw of dice he cannot see. The dice fall in the pirates’ favour, and the Admiral spends the next days losing a chase across the island as slowly as he can. Kyros returns to Rebecca not as a toy but as a father who lets her believe, for her own sake, that the soldier who protected her is gone. Riku takes the throne again, and Viola asks him to make Rebecca a princess.',
    'Sabo carries Ace’s fruit into a new life and slips away with the Revolutionaries and the weapons ledgers. Seven crews who fought beside Luffy for a day, Cavendish, Bartolomeo, Sai, Ideo, Leo, Hajrudin and Orlumbus, offer him their allegiance in a shared cup. He accepts the drink and refuses the command. The Straw Hat Grand Fleet, five thousand six hundred people, exists from that moment whether he likes it or not. Doflamingo is carried away in chains, and his bounty on Luffy is replaced by the Government’s: five hundred million berries.',
  ]),
], battles: [
  battle('usopp-sugar', 'Usopp versus Sugar · two shots that freed a country', '738–758', 'Knock out a child who has not aged in ten years, and return every toy in Dressrosa to the person it was.', 'The first attempt fails with a grape in Usopp’s mouth: the spice does its work on him rather than on Sugar, and the face he pulls is so terrible that she faints from fear. Hours later, revived and hunting the resistance, she is stopped by a shot from a mile away, aimed with an Observation Haki Usopp did not know he had.', 'Every toy becomes a person and every memory returns. Usopp, half dead, is declared a god by the dwarves and the freed, and the Birdcage that follows is Doflamingo’s admission that the mechanism holding his kingdom together has broken.', ['A grape laced with fire', 'A face that frightens a monster', 'Toys stand up as men', 'A sight across a mile of stone', 'One shot at a girl’s aura']),
  battle('kyros-diamante', 'Kyros versus Diamante on the sunflower field', '776–777', 'Kill the man who murdered Scarlett, in front of the daughter who was told her father was a toy.', 'Diamante fights with a rippling blade and a cape that turns steel to cloth and back, and with a mine field laid for Rebecca. Kyros fights with one leg and a sword that has not been in his hand for ten years. Rebecca throws herself between them when the mines are meant for her, and Kyros stops pretending to be anything but her father.', 'One cut, the same cut that beheaded a body double, ends Diamante. Kyros stands over the man who killed his wife and finds that the only thing he wants is for his daughter not to have watched.', ['Flowers hide the mines', 'A cape becomes a blade', 'A one-legged man runs', 'Scarlett’s name in the air', 'The sword comes down once']),
  battle('zoro-pica', 'Zoro versus Pica · the stone giant', '769–778', 'Bring down a man who has become the island’s own stone before he crushes the plateau where King Riku and the wounded wait.', 'Pica moves through every rock in Dressrosa and rebuilds himself as a colossus taller than the royal palace, and he is heading for the old king. Zoro is thrown into the sky by Orlumbus and the gladiators, cuts down through the stone body in pieces, and forces Pica to shrink his core to the size of a man to escape the blade.', 'A single strike finds the real body inside the stone. Pica falls, the mountain he was collapses across the island, and the last of Doflamingo’s executives on the field is gone.', ['A mountain grows a face', 'Thrown by a hundred hands', 'The stone comes apart in slices', 'One man inside the rubble', 'The giant loses its voice']),
  battle('luffy-doflamingo', 'Luffy versus Doflamingo · the Birdcage', '759–790', 'Break the man whose strings turn people into puppets and a country into a cage, before the wire slices the last survivors.', 'Doflamingo fights with parasite strings, flying threads that cut stone, and a technique that stitches his own wounds closed. Luffy is thrown back repeatedly until Gear Fourth changes the terms, then must be carried by allies for ten defenceless minutes while his Haki returns. Viola and Rebecca hold Doflamingo at the critical moment; the shrinking cage sets the clock.', 'King Kong Gun sends Doflamingo into the ground, the Birdcage dissolves, and the Warlord who manipulated a Government is finally arrested. Luffy earns a five-hundred-million bounty and, against his own wishes, a fleet.', ['Strings close over a country', 'Gear Fourth bounces upward', 'A Warlord thrown through his city', 'Ten minutes without Haki', 'Gatz counts down', 'The cage comes down']),
], legacy: [
  'Doflamingo’s arrest exposes the underworld the Warlord system protected, and his last taunt about the balance of power sits over every arc that follows. Kaido’s SMILE supply is severed, which forces the Emperor’s hand in Wano and makes the alliance a real target rather than a rumour. Sabo’s survival returns to Luffy a brother the reader also believed lost, and the Revolutionary Army’s presence hints at a war that operates on a different axis from pirates and Marines.',
  'The Straw Hat Grand Fleet, seven crews who chose Luffy without his consent, changes the crew’s standing without changing its size. Fujitora’s open defiance of the Government’s narrative and his refusal to arrest the pirates make him a Marine whose justice is his own. The Corazon flashback gives Law’s motives a weight that carries him through Wano, and the Op-Op Fruit’s rumoured power to grant eternal life begins to look like something the story is keeping in reserve.',
] }),

arc({ id: 'zou', name: 'Zou', sagaId: 'whole-cake-island', chapters: [802, 824], status: 'complete', premise: 'On the back of a thousand-year-old elephant, a people who kept faith are waiting to trust again.', locationIds: ['zou', 'thousand-sunny'], characterIds: CREW, overview: [
  'Zou is not an island but a living creature. The elephant Zunesha has walked the sea for a thousand years carrying a country on its back, and the Log Pose cannot lead anyone there because it never stands still. The Straw Hats climb its leg into a rainforest ruled by the Minks, animal people who greet strangers with either ferocity or unnerving affection. What they find at the top is a city recovering from an attack that ended only days earlier.',
  'Jack, one of Kaido’s three commanders, spent five days trying to make the Minks surrender a ninja none of them admitted to sheltering. They never broke. The ninja Raizo is a retainer of the Kozuki family of Wano, as are Kin’emon and Kanjuro, and Momonosuke is the heir. Zou is where the crew learns that the samurai they befriended are the remnants of a dynasty, that Wano is where Kaido lives, and that Zou holds one of four stones needed to find the last island.',
  'It is also where the crew is broken up again. Sanji has left with the Big Mom Pirates, carrying a name he never told his friends, and Luffy splits the company: one group to Wano with the Minks and samurai, another to Big Mom’s territory to bring the cook back. Zou is a short arc, but almost everything that drives the next two years of the story is set in motion in its final chapters.',
], beats: [
  beat('the-walking-island', 'Climbing the elephant', '802–804', [
    'Following Law’s vivre card, the Sunny and Bartolomeo’s ship reach a wandering landmass that turns out to be an animal so large that its back has its own climate. Usopp and Robin nearly drown when Zunesha bathes, and Luffy climbs the leg on foot in his impatience, with Kin’emon and Kanjuro dangling from the dragon Momonosuke has drawn. The rainforest above holds the ruins of a fight: buildings collapsed, a fortress at the elephant’s right belly, and a silence where a city should be.',
    'The first Minks they meet attack, then stop. Wanda, a dog Mink on a crocodile, and Carrot, a rabbit who bites first and asks afterwards, recognise the names Nami and Chopper and change entirely. Luffy is led through a forest of broken houses to a city that has been poisoned and rebuilt in a week, and the Minks who survived it treat the Straw Hats as saviours before anyone has explained why. Zoro, Usopp, Robin and Franky arrive by more dignified routes and find the same welcome.',
  ]),
  beat('the-guardians', 'The dog of the day and the cat of the night', '805–808', [
    'Nami and Chopper are alive and well, and the Minks treat the Straw Hats as saviours. Wanda explains that the crew’s friends arrived when the country was poisoned and dying, and that Chopper and Caesar, with much protest from the latter, cured the survivors. Brook, in the same week, has become a favourite of the Minks who find his skeleton adorable. The city is ruled in shifts: Duke Inuarashi governs the day and sleeps at dusk, Master Nekomamushi rules the night and sleeps at dawn, and the two have not spoken in years.',
    'The Minks’ affection is physical and unrelenting; Nami is groomed, Luffy is nuzzled, Zoro is offered enough liquor to keep him from asking questions. Inuarashi and Nekomamushi, both bandaged and both missing limbs, are gracious to their guests and cannot be in the same room together, and their retainers keep the rulers’ schedules apart with the care of people who have hidden a feud for a very long time. What nobody will say is why Jack attacked, or who the ninja he wanted was, or where that ninja is now.',
  ]),
  beat('jacks-attack', 'Five days under Jack', '807–810', [
    'Days earlier, Jack the Drought landed on Zou and demanded the ninja Raizo. The Minks denied knowing him, which was true for most and a lie for their two rulers. Jack’s answer was five days of siege. The Minks fought back with electro and the ferocity of their day and night guardians, Duke Inuarashi and Master Nekomamushi, and drove Jack to a stalemate that a fair fight might have turned into a victory.',
    'Jack ended the stalemate with Caesar’s poison gas, the weapon from Punk Hazard, and left the Minks crippled and burning while he went to rescue Doflamingo from the Marine convoy escorting him. He failed there, and Zou survived. Sanji’s group arrived in the aftermath and, with Caesar forced to help, saved the population. Inuarashi lost a leg and Nekomamushi an arm to their captor. The Minks never gave Raizo up, because a retainer of Kozuki Oden is a friend and a friend is a debt.',
  ], 'flashback'),
  beat('sanjis-departure', 'An invitation and a note', '811–813', [
    'The story of Sanji’s departure is told in pieces. Capone Bege arrived after Jack, with Pekoms, carrying an invitation from Big Mom to a tea party at which Sanji would marry her daughter Pudding. The invitation named him Vinsmoke Sanji, and the name meant something to Bege that it did not yet mean to the crew. Pekoms tried to warn Sanji off and was shot for it by his own comrade. Bege, whose Devil Fruit makes him a fortress with a garrison inside, held Nami, Chopper and Brook inside his body, and Sanji went with him rather than let them be hurt.',
    'He left a note saying he would come back, and Pekoms’ life was the price of his cooperation. Luffy hears all of this and responds with anger at the wrong person: he shouts at Nami for letting Sanji go, and she cries at being blamed for a thing nobody could have stopped. Brook has already worked out what the crew has not, that the Vinsmoke name belongs to a family of assassins and that Sanji has spent years not saying it. Luffy decides in a sentence that they will go and get him.',
  ]),
  beat('raizo-and-the-alliance', 'The ninja in the whale tree', '814–819', [
    'Nekomamushi leads the crew and the samurai to the whale-shaped tree in the forest where, it turns out, Raizo has been hidden all along. Kin’emon and Kanjuro, who spent the climb expecting to be told their comrade was dead, learn that a whole country was tortured for five days and never gave him up, and Kin’emon weeps into the fur of the two rulers who paid for it with their limbs. Raizo’s reveal is a moment of theatre: a ninja who is not what Luffy imagined and exactly what Wano would produce.',
    'Inside the whale, Momonosuke claims his lineage aloud as the son of Kozuki Oden, whose retainers Kin’emon, Kanjuro and Raizo have crossed twenty years to protect him. Oden, once a crewmate of Whitebeard and Roger, was executed by Kaido and the shogun Orochi for trying to open Wano to the world, and his retainers were sent forward in time by his wife to finish what he started. Inuarashi and Nekomamushi, feuding for reasons neither will name, agree to unite for the boy. The Minks, the samurai and the pirates form an alliance to take down Kaido and free Wano.',
  ]),
  beat('the-road-poneglyph', 'A red stone and a cook’s farewell', '818–824', [
    'The whale tree holds a Road Poneglyph, a red stone that gives a location rather than history. Nekomamushi explains that four such stones exist, that the coordinates they hold mark the final island, and that Big Mom and Kaido each guard one. Robin realises the crew has been given a route to the place Roger reached. Inuarashi adds that Nekomamushi will seek Marco, and that Kaido is not the only enemy: the Kozuki crest is a target for the World Government as well.',
    'Jack returns and attacks Zunesha itself, and Momonosuke hears the elephant asking permission to fight. Luffy gives it, and a single trunk swing destroys the fleet. The group divides: Zoro, Usopp, Robin, Franky and the samurai will go ahead to Wano, while Luffy takes Nami, Chopper, Brook and the Mink Pedro to bring Sanji back before the wedding. Sanji left a note saying he would return, and Luffy intends to hold him to it. Carrot stows away for the sake of the adventure.',
  ]),
], battles: [
  battle('jacks-assault', 'Jack’s assault on Zou', '807–809', 'Force a whole country to surrender one man, or destroy it trying; for the Minks, protect a guest without admitting he exists.', 'Jack’s mammoth form and his crew hammer the Mink city for five days, while Inuarashi and Nekomamushi trade shifts by daylight and darkness so that he never faces a rested defence. When strength fails, Jack resorts to Caesar’s gas and leaves.', 'Zou is poisoned but not broken. Raizo is never surrendered, the two rulers are maimed, and Jack’s failure to free Doflamingo leaves him with a grudge he will carry back to Wano.', ['A mammoth on the elephant’s back', 'Day shift, night shift', 'Electro against tusks', 'The gas rolls through the trees', 'A leg and an arm for a stranger']),
  battle('zunesha-strikes', 'Zunesha versus Jack’s fleet', '821–822', 'Save a thousand-year-old elephant, and the country on its back, from a commander who has decided to kill it outright.', 'Jack returns with his fleet and fires on Zunesha’s legs to bring the whole nation down into the sea. The elephant, forbidden to act without orders for a thousand years, asks a voice only Momonosuke and Luffy can hear for permission to defend itself, and Momonosuke gives it.', 'One sweep of the trunk sinks the fleet. Jack survives in the wreckage, and the crew learns that Zunesha is a prisoner serving a sentence, awaiting someone with the right to command it.', ['Cannons at the legs', 'A voice in a boy’s head', 'Permission granted', 'The trunk sweeps the sea']),
], legacy: [
  'The Road Poneglyphs convert the crew’s vague goal into a map. Robin now reads for coordinates as well as history, and the New World becomes a hunt for four stones held by the strongest people alive. The Ninja-Pirate-Mink-Samurai alliance gives the Wano campaign its shape before anyone has seen the country, and Momonosuke’s claim to his name begins turning a frightened boy into a ruler with a country waiting for him.',
  'Sanji’s departure and the note he left split the crew into the two halves that will fight the next two arcs. Zunesha’s voice, audible only to Momonosuke and Luffy, hints at connections to the Void Century that neither yet understands, and Jack’s survival guarantees that Kaido knows exactly who allied against him. The Minks, who kept faith with a man they had never met because of a promise made to Oden, model the loyalty that Wano will demand of everyone who enters it.',
] }),

arc({ id: 'whole-cake-island', name: 'Whole Cake Island', sagaId: 'whole-cake-island', chapters: [825, 902], status: 'complete', premise: 'A wedding invitation, a family that manufactures sons, and a rescue nobody agreed to be rescued from.', locationIds: ['whole-cake-island', 'cacao-island', 'mirror-world', 'thousand-sunny'], characterIds: ['luffy', 'nami', 'chopper', 'brook', 'sanji', 'jinbe'], overview: [
  'Big Mom’s territory is an archipelago of edible islands where every race in the world lives under one ruler. The Emperor herself, Charlotte Linlin, has dozens of children, a hunger that erupts into destruction, and a plan: marry her thirty-fifth daughter Pudding to the third son of the Vinsmoke Family, and gain the scientific war machine of Germa 66 in exchange. The third son is Sanji, who has never spoken of his family and now has a reason not to.',
  'Luffy comes with Nami, Chopper, Brook, and the Minks Pedro and Carrot, not to fight an Emperor but to retrieve a cook. Sanji refuses, violently, because the explosive cuffs on his wrists and the threat to the Baratie leave him no honest way to say yes. The arc turns that refusal into its centre: Luffy will wait, starving, until Sanji comes back on his own, and the wedding becomes an assassination plot involving pirates who hate each other.',
  'The escape from Whole Cake Island is one of the longest chases the series has staged, running through a mirror world, a collapsing castle, and a sea full of Big Mom’s children. Along the way Jinbe ends his service to the Emperor he owed, Brook steals a copy of a Road Poneglyph, and Luffy fights Katakuri in a duel that teaches him to see a few seconds ahead. Sanji bakes the cake that saves them all.',
], beats: [
  beat('totto-land', 'Into the Seducing Woods', '825–835', [
    'Luffy’s group sails the Sunny into Totto Land, where Big Mom’s sea patrols include ships crewed by her children and waters guarded by candy. Luffy eats a poisoned fish and is saved by a stranger who calls herself a friend: Germa’s Vinsmoke Reiju, who sucks the poison out and tells the crew that Sanji is a prince of a scientific kingdom whose mercenary army once ruled the North Blue. Pekoms, who came ahead to help, is shot by Bege for it. The Straw Hats have no allies here they can trust.',
    'A girl named Pudding, kind and eager, takes them in and promises to help stop a wedding she says she does not want either. Then the Seducing Woods separates the group: a forest of living trees and talking food where Brûlée’s mirrors put an enemy behind every reflection. Nami finds the tree Pound, who claims to be Lola’s father, and the Lola connection becomes a weapon when Nami produces the vivre card Lola gave her at Thriller Bark. Big Mom’s homies, the souls she plants in objects, bow to it.',
  ]),
  beat('germa', 'The kingdom that sails', '832–838', [
    'Sanji wakes inside Germa, a kingdom that is also a fleet, where the castles bolt together into a nation when the ships dock. His father Judge greets him as a failure recovered for use, and his brothers Ichiji, Niji and Yonji greet him as the punching bag they lost thirteen years ago. The soldiers are clones grown in vats; the princes are altered before birth to feel nothing. Sanji, offered a place at the table, kicks his father across the hall and is fitted with explosive cuffs for his trouble.',
    'Judge does not need Sanji’s consent, only his presence at an altar. The cuffs will take his hands if he runs, and Judge adds a second lock: the Baratie, and the old man who gave a boy his leg, will be visited if the wedding fails. Reiju treats the wounds her brothers leave and says nothing that could help. Sanji learns that his family sees the marriage as the purchase of an Emperor’s protection and that he is the coin. He stops trying to leave, and starts trying to decide whom he can afford to save.',
  ]),
  beat('iron-mask', 'The failed son of Germa', '839–841', [
    'Sanji was born the third of four sons to Vinsmoke Judge, who altered his children before birth to produce soldiers without empathy. Their mother Sora took a drug to counteract the modification, at the cost of her health, and only Sanji was born with his feelings intact. To Judge, that made him a failure. His brothers beat him for sport, his father declared him dead to the kingdom, and he was locked in a dungeon wearing an iron mask so no one would see his face.',
    'Reiju, the eldest and the only sibling who retained some kindness despite the modification, treated his wounds and eventually helped him escape when the family’s ships passed through the East Blue. Judge let him go on one condition: never tell anyone that he was a Vinsmoke. The boy who cooked for the dungeon rats found a ship, then a cook who would lose a leg for him. Sanji has spent his adult life honouring the condition, not out of loyalty to Judge but out of shame.',
  ], 'flashback'),
  beat('cracker', 'An army made of biscuits', '836–843', [
    'Charlotte Cracker, one of Big Mom’s three Sweet Commanders, arrives in the Seducing Woods as a knight in armour that turns out to be armour without a knight. His fruit bakes biscuits into soldiers, and every one Luffy breaks he replaces with two. The real Cracker, thin and vain, hides inside the shells. Luffy fights for eleven hours in the dark with Nami’s lightning as his only light, and the ground fills with crumbs that reassemble behind him. Pedro and Brook, elsewhere, are hunting the castle for a Poneglyph.',
    'The solution is Luffy’s and only his. Nami calls rain, the biscuits soften, and Luffy eats the army. He eats soldier after soldier, swelling into a shape that has no name, until Cracker has nothing left to hide behind and Tank Man, a Gear Fourth made of the enemy’s own bread, throws the commander through the forest and into the castle wall. Big Mom’s empire has not lost a Sweet Commander to an intruder in living memory. Luffy, full to bursting, marches toward the castle to find his cook.',
  ]),
  beat('luffy-and-sanji', 'A punch and a promise to starve', '843–849', [
    'Sanji meets Luffy on the road with Judge’s guards and, in front of his family, beats his captain to the ground. He calls Luffy a liar and the Straw Hats a burden, says that a prince has no use for a ship full of nobodies, and puts every kick in exactly where it will hurt. Luffy refuses to hit back, then refuses to leave. He sits down in the road where Sanji left him and says that he will wait there without food until his cook returns, because a captain who leaves without his cook cannot become the king of anything.',
    'Big Mom’s army comes for the boy in the road and finds a starving man who will not move and cannot be moved. Luffy and Nami are taken to the castle and locked in a living book while Big Mom questions them about Lola, whose name makes her want them dead. Brook, alone in the treasury, gets a rubbing of the Road Poneglyph and is caught by the Emperor herself. He fights her, a skeleton against a woman who cannot be hurt, and loses, but the rubbing is hidden in his skull before she picks him up as a toy.',
  ]),
  beat('pudding', 'A third eye behind a kind face', '850–856', [
    'Pudding shows Reiju her true face. The kind girl who wept about the wedding is a performer who has spent her life mocking everyone she fooled, and the plan for the altar is a bullet through Sanji’s head and a massacre of every Vinsmoke in the hall. Sanji, coming to her window with flowers, hears every word. Big Mom, asleep and talking, reveals to Nami and Luffy the whole arrangement: Germa’s science bought, Germa’s family killed. Jinbe walks into the prison, opens the book, and tells them that he has come to leave this crew.',
    'Sanji brings Luffy food in the rain and finds him where he left him, starved to bone and immovable. He admits that he wants to go home and cannot bear to abandon his family to death, even a family that put him in a mask. Luffy tells him to save them and then come back, because that is what a Straw Hat would do. Pedro, Chopper and Carrot have been fighting Brûlée inside her own mirrors and have captured her, and the Mirror World becomes the crew’s road into the castle nobody has ever escaped from.',
  ]),
  beat('the-tea-party', 'A wedding and a scream', '857–872', [
    'Capone Bege, a Big Mom subordinate who wants to kill her, allies with the Straw Hats for one day. The plan uses a portrait of Mother Carmel, the woman who raised Linlin, because breaking it once made her scream so hard she collapsed. At the altar Pudding fails to shoot Sanji, undone by his compliment of her third eye. Brook shatters the portrait, Big Mom screams, and Bege’s rocket launchers fail against a ruler who feels no pain. Jinbe announces his resignation from her crew and refuses her roulette.',
    'Big Mom’s childhood on Elbaf surfaces as she screams: a giant’s orphanage, a feast that ended with the disappearance of Carmel and every child, and a rage for sweets she has never understood. Caesar flies Bege’s castle body out of the hall while the Tamatebako, the chest Fish-Man Island sent to Big Mom as tribute and rigged years earlier against thieves, detonates at the base of the castle. The Whole Cake Chateau collapses, and the Straw Hats run for the ship with the Vinsmokes at their side.',
  ]),
  beat('the-hunt-for-a-cake', 'Pedro, the mirror, and the missing cake', '873–884', [
    'Big Mom, deprived of the wedding cake, becomes a craving that walks: a rampage that levels whatever stands between her and sugar. Sanji proposes to bake a replacement cake so exquisite it will pacify her, and Pudding, whose loyalties have shifted, joins him with Chiffon, Lola’s twin. The rest of the crew retreats through the Mirror World toward the Sunny, pursued by Perospero’s candy and Big Mom herself, who has boarded the ship and tears at its deck.',
    'Pedro, the Mink who came to repay a debt to Luffy for freeing Zou, detonates himself against Perospero to open the crew’s way to the sea. Luffy stays behind in the Mirror World to break every mirror leading to the Sunny and to fight the one pursuer he cannot outrun: Charlotte Katakuri, the strongest of Big Mom’s children, whose Observation Haki lets him see seconds into the future. The plan is now three simultaneous races: a cake, a ship, and a duel.',
  ]),
  beat('cacao-island', 'Future sight and an open sea', '885–902', [
    'Katakuri is a fighter without flaws, and the flaw Luffy discovers is human: the commander eats lying down, in secret, because his mouth embarrasses him. When Luffy sees it, Katakuri punishes his own sister for exploiting the moment, and the duel becomes a matter of honour between two men who refuse cheap victories. Luffy slowly learns to glimpse the future himself, and Snakeman, a Gear Fourth built on speed rather than force, lands the final exchange. Katakuri, defeated, asks if Luffy will return to beat Big Mom, and accepts the answer.',
    'The Sunny reaches Cacao Island at the appointed hour, where the entire Big Mom armada waits. Germa 66, whose sons Sanji saved, intervenes with a violence Sanji does not thank them for, and Big Mom finally tastes the cake. Jinbe stays behind with the Sun Pirates to hold the strait, promising to rejoin at Wano. The crew escapes a sea full of enemies with every ship they can see behind them, and a newspaper is already being printed that will call a rescue mission a war against an Emperor.',
  ]),
], battles: [
  battle('luffy-cracker', 'Luffy versus Cracker in the Seducing Woods', '836–843', 'Reach the castle through a Sweet Commander whose army rebuilds itself from crumbs, before dawn brings the rest of the family.', 'Cracker fights from inside biscuit knights that reform faster than Luffy can smash them, while the real man stays hidden and unhurt. Eleven hours pass in the dark. Nami’s rain softens the shells, and Luffy begins to eat his way through the army rather than break it.', 'A Gear Fourth swollen with Cracker’s own biscuits hurls the commander out of the forest. Big Mom’s crew has lost a Sweet Commander to an intruder for the first time, and Luffy walks toward the castle with an army in his stomach.', ['A knight with nothing inside', 'Eleven hours in the dark', 'Rain softens the shells', 'Luffy eats the enemy', 'Tank Man throws a commander']),
  battle('luffy-sanji', 'Sanji versus Luffy on the road to the castle', '843–844', 'Make a captain leave without his cook, in front of a family that must believe the cook means it.', 'Sanji attacks with everything he has and Luffy blocks nothing. Each kick is aimed to injure and each word to drive him off, and Luffy takes both until he is on the ground with his hat in the dirt. Then he stands up and refuses to go.', 'Sanji walks away to a wedding he does not want, and Luffy sits down in the road to starve until his cook comes back. Neither man has won, and both have said exactly what they meant.', ['A kick the captain does not block', 'Words chosen to wound', 'A hat in the dirt', 'He sits down and waits']),
  battle('tea-party-assault', 'The tea party assassination', '860–872', 'Kill an Emperor at her own daughter’s wedding using a photograph, a skeleton, and a crew of men who despise each other.', 'Pudding fails to shoot, Brook shatters Mother Carmel’s portrait, and Big Mom screams as the plan requires. But Bege’s rockets do nothing to a woman whose skin refuses to break, and the whole hall turns on the conspirators. Jinbe names himself a traitor to her face, Luffy vomits out the wedding cake he was hiding in, and the Vinsmokes, unmasked as the intended victims, fight for their lives in raid suits.', 'The assassination fails and the escape succeeds. Bege’s fortress carries the alliance out of the hall, the Tamatebako detonates under the chateau, and Big Mom is left screaming for a cake that no longer exists.', ['A bullet that does not fire', 'A portrait breaks', 'The Emperor screams', 'Rockets on unbroken skin', 'Jinbe refuses the roulette', 'The chateau comes down']),
  battle('luffy-katakuri', 'Luffy versus Katakuri in the Mirror World', '879–896', 'Hold the strongest of Big Mom’s children inside the mirrors long enough for the Sunny to reach Cacao Island, and destroy every route by which he could follow.', 'Katakuri’s future sight and mochi body make Luffy’s attacks land on nothing. Luffy takes hours of punishment, learns to sense the commander’s intentions, and is nearly killed while a subordinate interferes. Katakuri wounds himself to restore the fairness of the duel, and the two fight without deceit until Luffy’s new form outpaces prediction.', 'Snakeman drives Katakuri into the mirror floor. He falls beside Luffy and asks a question about the future, then lets the exhausted pirate leave through the last mirror Brûlée can open.', ['A mouth behind the scarf', 'Hours of borrowed future', 'A wound made by choice', 'Two men see the same second', 'Snakeman finds the opening', 'A question about the future']),
], legacy: [
  'Sanji’s name is out, and his refusal of Judge’s offer of the Vinsmoke inheritance gives the crew a cook who has chosen his family twice. The Big Mom Pirates are now an enemy with a memory, and the copy of Big Mom’s Road Poneglyph gives the crew two of the four coordinates. Jinbe’s public break with the Emperor and his promise to reach Wano keep the recruitment begun on Fish-Man Island alive, at the price of leaving him behind in enemy waters.',
  'Luffy’s Future Sight and the Snakeman form are the tools he will need against Kaido, and Katakuri’s conduct lets an enemy commander be honourable without weakening him. Big Mom’s Elbaf childhood plants the giants and Mother Carmel in the deep history of the story. The newspaper’s judgement of this arc, declaring Luffy a fifth Emperor, reshapes how the world hears his name, while the raid suits and Germa’s cold science remain in the world, unresolved and unrepentant.',
] }),

arc({ id: 'levely', name: 'Levely', sagaId: 'whole-cake-island', chapters: [903, 908], status: 'complete', premise: 'While the world argues about a fifth Emperor, its kings gather beneath a throne that should be empty.', locationIds: ['mary-geoise'], characterIds: [], overview: [
  'The Levely is a council of kings convened every four years at Mary Geoise, the Holy Land atop the Red Line. Fifty rulers attend to argue about the shape of the world under the eye of the Five Elders. The manga interrupts its pirate story to show that gathering, and to follow the people the Straw Hats have loved and left: Vivi, Shirahoshi, Rebecca, Dalton and Kureha, each representing a country the crew once fought for and none of them free to say so.',
  'The interlude has two layers. On the surface, the newspapers announce Luffy as a fifth Emperor of the Sea after Whole Cake Island, the Revolutionary Army prepares to declare war on the Celestial Dragons, and old friends meet in a palace where Sabo’s group hides on a rescue mission. Beneath it, the story shows what Mary Geoise actually is: a place with an empty throne that no king may sit upon, and a figure who sits there anyway.',
], beats: [
  beat('the-fifth-emperor', 'A headline crowns a pirate', '903', [
    'Morgans, the president of the World Economic News Paper, turns the escape from Whole Cake Island into a story about a war. Under his editorial hand, Luffy becomes the leader of a fleet of thousands, the Straw Hat Grand Fleet appears as a standing army, and the world learns the new bounty: one and a half billion berries. The crew reads the news aboard the Sunny with a mix of embarrassment and delight, and Luffy declares that fifth is a step behind first.',
    'The same page lands on every desk that matters. Kaido reads it and Big Mom reads it, and the seven captains of the Grand Fleet read it and celebrate a war they did not fight. At Marine Headquarters, Sengoku laughs and Sakazuki does not. On Fish-Man Island, a princess who was promised a walk on the surface learns that the pirate who made the promise now stands beside the woman who protects her home, in the world’s estimation if not yet in fact.',
  ], 'interlude'),
  beat('the-revolutionaries', 'An army decides on a war', '904', [
    'In the Kamabakka Kingdom, the Revolutionary Army’s commanders assemble around Dragon for the first time since the loss of Baltigo. Sabo, Karasu, Morley, Lindbergh and Belo Betty are introduced as leaders of a movement the story has only glimpsed: a woman whose flag makes crowds brave, a crow-man who moves as a cloud of birds, a giant who tunnels through the earth. Dragon announces that they will strike directly at the Celestial Dragons during the Levely, when the whole world is watching Mary Geoise.',
    'Koala and Hack relay news of Kuma, the former Warlord who was a comrade of theirs before Vegapunk took his mind, and who is now kept in Mary Geoise as a slave for the nobles to ride. The army decides to bring him home whatever the council decides. Sabo asks whether Luffy, now a headline, will be a problem, and Dragon answers only that his son has been a problem since he was born. The rescue party leaves for the Red Line in disguise.',
  ], 'interlude'),
  beat('the-royals-gather', 'Old friends in a holy city', '905', [
    'Ships converge on the Red Line. Vivi and Cobra arrive from Alabasta with Igaram and Pell, Rebecca and Viola escort King Riku from Dressrosa, Dalton and Kureha represent the Sakura Kingdom, and Neptune brings Shirahoshi to her first Levely with Garp assigned as escort. Wapol, restored to a small throne through his wife’s wealth, arrives too and is delighted by everyone else’s misfortune. The friends recognise one another through shared stories about a straw-hatted pirate that none of them may speak aloud in front of the guards.',
    'Admiral Fujitora meets Admiral Ryokugyu, who has not eaten in three years and jokes about it, and the two discuss ending the Warlord system that let Doflamingo and Crocodile rule kingdoms. Sabo, Karasu, Morley and Lindbergh, disguised among the servants, watch the kings file past and keep their eyes on the slave quarters. Shirahoshi, who has never left the sea, is carried up the Red Line in a bubble and finds the Holy Land as beautiful and frightening as her mother said it would be.',
  ], 'interlude'),
  beat('a-saint-and-a-princess', 'The debt a Celestial Dragon owed', '906', [
    'Saint Charlos, the Celestial Dragon Luffy once punched at Sabaody, sees Shirahoshi and decides she will be his pet. His men throw a net over a princess in the heart of the world’s government, in front of every king present, and none of them may raise a hand. Vivi and Rebecca move anyway. Garp, forbidden to interfere, plans a distraction that will cost him his rank. Then another noble strikes Charlos down with a club. Saint Mjosgard, whose life Otohime saved on Fish-Man Island, has spent ten years remembering it.',
    'Mjosgard takes Shirahoshi under his protection and declares her untouchable, and Charlos is carried away raging. Shirahoshi’s tears, held back with all the courage she learned at home, mark how far Otohime’s hope has travelled in a single generation: one Celestial Dragon has become a human being because a mermaid refused to hate him. Vivi and Rebecca compare the men they know who wear a straw hat, and the Revolutionaries in the corridor above see where the slaves are kept.',
  ], 'interlude'),
  beat('the-empty-throne', 'What sits above the Five Elders', '907–908', [
    'Shanks walks into Mary Geoise to speak privately with the Five Elders about a certain pirate, a conversation the reader is not allowed to hear. Elsewhere Big Mom telephones Kaido and reminds him of an old debt, and the two Emperors agree, ominously, to meet in Wano. The world’s power blocs are moving in the same direction at once, and the kings who argue in the chamber below have no idea how little their debate will decide.',
    'At the heart of the Holy Land stands the Empty Throne, surrounded by twenty weapons, a monument to the promise that no single ruler will govern the world. A figure called Im climbs the steps and sits on it, and the Five Elders kneel. Im examines wanted posters of Luffy and Blackbeard and portraits of Shirahoshi and Vivi, and destroys one of them. Cobra, meanwhile, prepares to ask the Elders about the Poneglyphs, a question the Nefertari family has been owed an answer to for eight hundred years.',
  ], 'interlude'),
], battles: [
  battle('a-war-of-headlines', 'A war of headlines', '903', 'Decide what the world believes happened at Whole Cake Island before anyone can check.', 'Morgans chooses the version that sells: a pirate who invaded an Emperor’s territory and left with her fleet in ruins. Kings, Marines and rival crews read the same page and draw opposite conclusions. The Straw Hats can neither confirm nor deny the fleet they never commanded.', 'Luffy is named the fifth Emperor, his bounty jumps to one and a half billion, and the world reorganises its fears around a crew of ten people and one lion-headed ship.', ['Ink dries on a bounty', 'Kings read the same paper', 'Two Emperors read it too', 'A crew laughs at its legend']),
  battle('charlos-and-mjosgard', 'Saint Mjosgard strikes Saint Charlos', '906', 'Keep a mermaid princess out of a noble’s collection, in a city where no king may touch a Celestial Dragon.', 'Charlos’s men net Shirahoshi in the corridor of the Holy Land, and every ruler present is bound by law to look away. Vivi and Rebecca break the law by moving; Garp weighs his career. Mjosgard, a Celestial Dragon who owes his life to Otohime, arrives with a club and no interest in the rules.', 'Charlos is struck down and carried off, and Shirahoshi is placed under a Celestial Dragon’s protection. For one afternoon, Otohime’s belief that a human could change has a witness in Mary Geoise.', ['A net over a princess', 'Kings who cannot move', 'A club in a noble’s hand', 'Tears held back']),
], legacy: [
  'The Levely leaves the world with questions rather than answers. Im and the Empty Throne overturn the Government’s founding story, and the Five Elders are revealed as servants rather than masters. Shanks’s visit and the Emperor alliance forming between Big Mom and Kaido establish the stakes that Wano will inherit. Sabo’s presence in the Holy Land guarantees that the council will not end quietly, though the story withholds the outcome for hundreds of chapters.',
  'The fifth Emperor headline changes how every faction speaks to Luffy. Allies who once saw a lucky rookie now see a peer of the Emperors, and enemies plan around a fleet that does not exist. Vivi’s and Shirahoshi’s appearances remind the reader that the crew’s completed arcs left people behind who are living with the consequences, and that the Nefertari and Ryugu families hold histories that Im is watching closely.',
] }),

arc({ id: 'wano', name: 'Wano Country', sagaId: 'wano', chapters: [909, 1057], status: 'complete', premise: 'Twenty years after a lord was boiled alive, his retainers return to open a country Kaido closed.', locationIds: ['wano-country', 'flower-capital', 'udon', 'ringo', 'onigashima', 'thousand-sunny'], characterIds: [...CREW, 'jinbe'], overview: [
  'Wano is a closed country, sealed from the world by its own tradition and then by Kaido, who rules it through the shogun Orochi. Its people live in a fantasy of the Flower Capital while the surrounding regions starve, drink from poisoned rivers, and dig weapons in the Udon mines. Twenty years earlier the daimyo Kozuki Oden, who had sailed with Whitebeard and Roger and seen the last island, was executed for trying to open it again. His retainers were sent forward in time with his son, and they arrive now.',
  'The Straw Hats enter in disguise, one group ahead and one behind, and are almost immediately scattered. Luffy fights Kaido too early and loses so completely that he wakes in a prison mine. The arc spends its first half building an army out of prisoners, courtesans, shamed samurai and the crew’s own patience, and its second half burning that army against Onigashima, the island fortress where two Emperors have gathered to celebrate a festival and plan a war.',
  'The raid is the longest sustained battle in the manga. Nine retainers charge the man who killed their lord; a generation of pirates tests itself against two Emperors on a rooftop; and Luffy is knocked from the sky, drowned, and returns changed into something that laughs. Wano ends with a shogun crowned, a people freed, and a world in which the balance of power, and the names on the Emperors’ list, have been rewritten.',
], beats: [
  beat('a-closed-country', 'Samurai in disguise', '909–924', [
    'Zoro arrives first, framed for murders by a corrupt magistrate and forced toward seppuku until he cuts his way free. Luffy loses the Sunny to a waterfall and washes ashore in the poisoned region of Kuri, where a girl named Tama shares the water she has been saving for the day Ace returns. Ace is dead, and Luffy cannot tell her. The others arrive as Kin’emon’s plan dictates, taking Wano names and occupations: a geisha, a dancer, a ronin, a carpenter, a shrine-thief who steals from the rich to feed the leftover towns.',
    'Kuri is the country outside the capital: rivers that run with factory waste, a town called Leftovers that eats what Bakura discards, and a headman who keeps Tama as a bait for animals. Luffy beats Kaido’s men in Bakura Town for her sake, with Zoro and the samurai Kikunojo beside him, and flees to the ruins of Oden Castle, where Kin’emon lays out the plan: gather allies in secret, and strike Onigashima on the night of the Fire Festival, when Kaido’s crew will be drunk. The graves of Oden and his retainers stand behind him as he speaks.',
    'Luffy breaks the plan within a day. When Kaido himself arrives in Kuri, drunk and in dragon form, hunting for Law and levelling the castle ruins in his boredom, Luffy attacks him alone. He hits the Emperor with everything Gear Fourth has and stops him for a moment. Kaido’s club puts him down in a single blow. Luffy wakes in the Udon prisoner mine wearing sea-stone cuffs, and Kaido tells Law that he wants the boy alive and broken, so that he can be made into a soldier who has forgotten how to lose.',
  ]),
  beat('udon-and-the-capital', 'A prison mine in Udon', '925–949', [
    'In Udon, Luffy hauls stone beside the old yakuza boss Hyogoro, once the most respected man in the Flower Capital and now a starving prisoner, and learns from him the advanced Armament Haki that flows into an enemy without touching him. Queen, one of Kaido’s commanders, turns the mine into a sumo arena where the losers are executed, and then, when the prisoners will not die fast enough, into a slaughterhouse with a plague. Raizo slips inside to steal the keys to Luffy’s cuffs, and finds Kawamatsu, another of Oden’s retainers, thirteen years in a cell.',
    'Big Mom arrives in Wano to collect a debt from Kaido, loses her memory in a fall from the waterfall, and is brought to Udon by Chopper and Tama as a hungry, harmless woman who wants only red bean soup. Queen has eaten it all. The uprising that frees the prisoners begins when she remembers who she is, and it ends with Luffy, cuffs broken by Raizo’s key, standing on Queen’s back with a mine full of men who have watched him spend days refusing to fall. Udon becomes the rebellion’s barracks, and its prisoners its army.',
  ]),
  beat('the-flower-capital', 'A poisoned city laughs', '927–958', [
    'In the Flower Capital, Orochi holds a banquet where the courtesan Komurasaki is apparently killed for refusing his hands, and where Robin, spying as a geisha, is nearly caught by the shogun’s ninja. In Ebisu Town, the poor laugh at everything because Orochi fed them defective SMILE fruits that stole their ability to express anything else. Yasuie, a former daimyo, is executed after claiming the Kozuki plot was his own joke, and the crew watches a town laugh at his death while its eyes stream.',
    'Zoro protects the girl Toko, whose father has just been shot, and finds Komurasaki alive: she is Hiyori, Oden’s daughter, hidden for twenty years in plain sight. In the snows of Ringo she gives him Enma, her father’s sword, a blade that drains the Haki out of whoever holds it and cut the only wound Kaido has ever carried. Kaido and Big Mom, after fighting for a day and a night, agree to an alliance to take the world. Kanjuro, unknown to anyone, is a Kurozumi spy who has been feeding Orochi every plan since Zou.',
    'When the retainers reach the port where their allies should be waiting on the night of the festival, the ships are gone. Orochi believes he has ended the rebellion before it began, and the news from outside the country says that the Warlord system has been abolished and the Marines are turning on their own former allies. The story pauses here, with the samurai staring at an empty harbour, to explain who Oden was and why twenty years of waiting were worth it.',
  ]),
  beat('oden-the-wanderer', 'The man who left Wano', '960–966', [
    'Kozuki Oden was the heir of Wano’s shogun and a disaster as a son: a child who lifted boulders, dammed rivers by mistake, and made a habit of fighting mountain gods. Exiled to the wasteland of Kuri, he tamed it into a prosperous region and became its daimyo. His retainers were gathered from castaways, orphans and thieves: Kin’emon, Denjiro, Kanjuro, Raizo, Ashura Doji, Kikunojo, Kawamatsu, Izo, and Inuarashi and Nekomamushi, the two Minks whom Wano had abused as monsters.',
    'When Whitebeard landed on Wano, Oden clung to his ship’s chain for three days demanding to be taken aboard, and was. He married Toki, a woman born eight hundred years earlier who had used a Devil Fruit to travel forward. He met Roger, and Roger asked him to read a Poneglyph. Oden left Whitebeard for a year to join Roger’s final voyage, reached the last island with him, and heard the story that made Roger laugh. He wrote it down and never showed anyone alive.',
  ], 'flashback'),
  beat('odens-death', 'The lord who was born to boil', '967–972', [
    'Oden returned to Wano to find Orochi installed as shogun and Kaido occupying the country. For five years he did nothing but dance naked in the capital each week, and his people called him a fool. The truth, told only afterwards, was that Orochi had threatened to slaughter Wano’s citizens unless he humiliated himself, and Oden agreed rather than test the threat. When he finally attacked with his retainers, Kaido was warned, and the raid on Onigashima failed.',
    'Oden and his retainers were sentenced to boil in oil. He carried them all on a plank above the cauldron for an hour, buying their survival with his own skin, and asked only that Wano be opened before the day, twenty years hence, when a figure of liberation would be needed. Kaido shot him himself. Toki sent Momonosuke, Kin’emon, Kanjuro, Raizo and Kikunojo twenty years forward, and stayed behind to die. Her poem about nine shadows and a dawn became the country’s only hope.',
  ], 'flashback'),
  beat('onward-to-onigashima', 'The traitor and the promised port', '973–982', [
    'The allies were never lost: Denjiro, who has spent twenty years as the yakuza boss Kyoshiro, moved the ships and freed the prisoners Orochi thought he had captured. Kanjuro is exposed and reveals his contempt with a laugh, then carries Momonosuke off to Onigashima on a bird of ink. Kin’emon’s misdirection of the traitor turns out to be luck he does not confess to. Jinbe, promised at Whole Cake Island, arrives at sea in his own ship, having brought the Sun Pirates through the Emperor’s waters, and takes his place as helmsman of the Straw Hats.',
    'The fleet of samurai, Minks and three pirate crews reaches Onigashima under the cover of the Fire Festival. Luffy, Kid and Law argue over who will strike Kaido first and are stopped by the Beasts Pirates’ ships before they land. Inside, the Straw Hats scatter through a fortress full of drunken Beasts Pirates dressed as their enemies. Luffy is drawn away by the sight of food being wasted, and meets Kaido’s child, a masked figure who has been waiting for someone exactly like him to arrive.',
  ]),
  beat('yamato', 'A son who calls himself Oden', '983–999', [
    'Yamato, Kaido’s child, tore up Oden’s journal as a boy, read every word, and decided to become Oden instead of his father’s heir. Kaido answered with sea-stone handcuffs that will explode if Yamato ever leaves the island. Meeting Luffy, Yamato removes the mask and swears to fight beside him, because the journal says that on this night a man would come who could open Wano. Yamato has spent twenty years defending Oden’s grave from Kaido’s men and calling the retainers who left him behind by name.',
    'Yamato finds Momonosuke and tells him the story of Ace, who once landed on Onigashima to fight Kaido and left behind a promise instead of a scar. Kaido announces his New Onigashima Project from a stage, revealing that he intends to move the island onto the capital and turn Wano into a weapons state with a slave class, and orders Momonosuke to declare the Kozuki cause dead. Yamato breaks his own cuffs open and joins the raid, and Kaido learns that his child has become the enemy his enemy left behind.',
  ]),
  beat('the-rooftop', 'Two Emperors and a new generation', '990–1014', [
    'The Nine Red Scabbards reach the roof and charge Kaido with the same wounds Oden once left on him, and for a few pages the impossible looks possible. Kaido shrugs off every blade, and the retainers fall. Luffy, Zoro, Kid, Law and Killer climb to face two Emperors in a fight that turns the roof into a crater. Zoro takes a blow meant for everyone and is broken; Law carries the Emperors’ attention; Luffy’s Conqueror’s Haki, coating his fists, hurts Kaido for the first time.',
    'Below, the crew fights its own war: Sanji against Black Maria’s women, Robin and Brook in the treasury, Nami and Usopp protected by Otama’s tamed beasts, Franky against Sasaki, Jinbe against Who’s Who, who reveals that the Marines once guarded the Gum-Gum Fruit for the Government. Kaido knocks Luffy off the roof and into the sea, then announces to the fortress that Straw Hat Luffy is dead. Momonosuke, held on the stage, is ordered to declare the alliance lost, and refuses.',
  ]),
  beat('the-commanders-fall', 'The commanders fall one by one', '1015–1040', [
    'Luffy is pulled from the sea by Law’s crew and returns, and the fortress learns through Otama’s tamed announcer that the captain lives. Sanji beats Queen after accepting the Germa body that saves his life and choosing to remain a man who protects women rather than a machine that cannot. Zoro cuts King, the last of the Lunarians, with Enma tamed to his hand, and learns that the black flame on King’s back goes out when he chooses speed over armour. Robin destroys Black Maria as a demon.',
    'Kid and Law, fighting an Emperor two on one for the first time in their lives, drop Big Mom into the magma beneath the island with a combination of magnetism and a scalpel that hits from the inside. Yamato holds the explosives room against Kaido’s men, and Momonosuke, aged into a dragon by Shinobu’s fruit, tries to stop Onigashima from falling on the capital while it burns. The alliance that landed with five thousand people is down to hundreds, and every commander of the Beasts Pirates lies on the floor.',
  ]),
  beat('the-dawn-of-wano', 'The drums of liberation', '1041–1049', [
    'Kaido beats Luffy again, and again, and then Luffy’s heart stops. What wakes him is his Devil Fruit revealing its true name: the Human-Human Fruit, Model Nika, a mythical Zoan that grants a body of freedom, drawn in a style borrowed from cartoons, and a laugh that has no strategic value. Gear Fifth turns the battle into a fight against a dragon by a rubber god, who grabs lightning, turns the floor to rubber, and seizes Kaido’s dragon form by the head and skips it across the roof.',
    'Kaido meets it with clubs, with the last of his sake, and with a flame dragon that is the strongest thing he has ever been. Momonosuke lends his flame clouds to keep Onigashima in the air a little longer, and the country below watches a fist the size of the island come down on the man who owned them. Kaido is driven into the magma beneath Wano, and Luffy’s last punch leaves a fist-shaped hole in the sky. The drums that Zunesha heard from the sea fall silent, and the sun comes up on a country that has not seen a free dawn in twenty years.',
  ]),
  beat('a-new-morning', 'Momonosuke opens the country', '1050–1057', [
    'Momonosuke, twenty-eight years old in body and eight in heart, becomes shogun. Onigashima lands safely thanks to his flame clouds, and Wano holds a festival that lasts as long as its wounds. Hiyori plays Oden’s song. Toki’s poem is fulfilled in ways nobody planned: the nine shadows, the dawn, and the wounded pirates who did not know they were part of a prophecy. The crew learns that Ashura Doji and Izo died in the raid, and Zunesha appears offshore asking the new shogun to open the border.',
    'The world reorganises: Buggy and Luffy are declared Emperors alongside Shanks and Blackbeard, Luffy’s bounty rises to three billion, and Crocodile and Mihawk join Buggy in Cross Guild, a company that puts bounties on Marines. Admiral Ryokugyu lands to finish what Kaido left and is turned away by Shanks’s Conqueror’s Haki from beyond the horizon. Momonosuke chooses to keep Wano closed a little longer, until the country can defend itself. Yamato stays to see it. The Sunny sails, and Luffy trusts Momonosuke to open the borders when the time is right.',
  ]),
], battles: [
  battle('scabbards-charge', 'The Nine Red Scabbards charge', '986–993', 'Give Kaido the death Oden could not, and pay twenty years of waiting with one night of steel.', 'Kin’emon, Denjiro, Kikunojo, Kawamatsu, Raizo, Ashura Doji, Izo, Nekomamushi and Inuarashi break through the stage and reach the roof. Each strikes with Oden’s techniques, and Kaido, remembering the wound that man left, bleeds. It is not enough. He recovers, and the retainers, spent, are cut down one by one.', 'The Scabbards fall but survive long enough to hand the fight to the next generation. Kaido has been reminded that he can bleed, and the alliance has proof that the impossible is only expensive.', ['Nine blades on a rooftop', 'Oden’s wound reopens', 'A dragon in the snow', 'The dragon shrugs them off']),
  battle('sanji-queen', 'Sanji versus Queen', '1022–1034', 'Beat a commander who is also a Germa-obsessed scientist without becoming the Germa weapon his father built.', 'Queen fights with a cyborg body, a plague of ice, and the Vinsmoke techniques he has copied out of envy, and taunts Sanji with the family he ran from. Sanji’s own body is changing: the raid suit has switched on something in his blood, and he finds himself able to shrug off blows that should kill him and to hurt women without noticing. He asks Zoro to kill him if it goes further.', 'Sanji chooses the man over the machine and beats Queen with a fire no Germa lab produced. The commander is kicked through the fortress, and Sanji’s hands and feet remain his own.', ['A brachiosaur in a lab coat', 'Ice that eats a corridor', 'A body that will not bruise', 'A request to Zoro', 'Fire that does not come from science']),
  battle('zoro-king', 'Zoro versus King', '1022–1035', 'Bring down the last of the Lunarians and the first of Kaido’s commanders, with a sword that is trying to kill its owner.', 'King fights in fire and in a pteranodon’s shape, and his body ignores blades whenever the flame on his back burns. Enma drains Zoro’s Haki with every stroke, and he is bleeding from wounds the rooftop left. He notices that the flame goes out when King moves fast, and that a body without flame can be cut.', 'Three swords and a Conqueror’s Haki Zoro did not know he had cut King out of the sky. He falls from Onigashima into the sea, and the flame that made Lunarians a myth goes out.', ['Wings of fire in a black corridor', 'Enma drinks its owner', 'The flame goes out when he runs', 'A cut that carries a king’s colour', 'The last Lunarian falls']),
  battle('kid-law-big-mom', 'Kid and Law versus Big Mom', '1038–1040', 'Take an Emperor off the board with two Worst Generation captains who cannot stand each other, before she rejoins Kaido on the roof.', 'Big Mom fights with a homie that eats souls and a body that has never been hurt, and she takes both captains apart for most of the fight. Law learns to put his scalpel inside her and strike from within; Kid learns to make a railgun out of the fortress. Neither works alone, and each insists he is not helping the other.', 'A shock wave from inside and a bolt of metal from outside drive Big Mom through the floor into the magma beneath the island. The two captains fall beside each other and refuse to be carried by the same men.', ['Two captains who will not cooperate', 'A scalpel from the inside', 'A railgun made of a wall', 'The Emperor goes through the floor']),
  battle('luffy-kaido', 'Luffy versus Kaido on the rooftop and beyond', '923; 1000–1049', 'Defeat the strongest creature in the world on the island he has made a fortress, before it crashes onto the capital.', 'Luffy is beaten at Oden Castle, knocked into the sea from the rooftop, beaten again in the fortress, and has his heart stopped by a final blow. Each return brings a new answer: Conqueror’s Haki that coats the fists, then the awakening of a mythical Zoan that lets him treat his body and the world as rubber. Kaido meets each escalation with clubs, drunkenness, and a dragon form powered by flame clouds.', 'A fist the size of the island meets a dragon’s head above Onigashima. Kaido falls into the magma beneath Wano beside Big Mom, and the country that was to be a weapons state becomes a nation again.', ['A club at Oden Castle', 'Conqueror’s colour on a fist', 'Knocked from the roof into the sea', 'The heart stops, then laughs', 'Rubber against a dragon', 'A hole in the sky']),
], legacy: [
  'Wano is the end of the Beasts Pirates and the Big Mom Pirates as powers, and the end of the Emperor system as the story knew it. Luffy’s Devil Fruit is revealed as a mythical Zoan the Government has hunted for eight hundred years, which turns his existence into a political fact. The Road Poneglyph on Onigashima gives the crew three of four coordinates, and Oden’s journal, read by Momonosuke and Yamato, confirms that the world’s true history waits at Laugh Tale.',
  'Jinbe’s formal joining completes the crew’s roster, and the Ryokugyu incident shows an Admiral meeting Shanks’s Haki and flinching. Cross Guild inverts the bounty system, Buggy becomes an Emperor by accident, and the Government’s attention now turns to the crew directly rather than to the pirates around them. Wano stays closed by its own choice, with a shogun who understands his father’s dream and a promise from Luffy to return when the borders open.',
] }),

arc({ id: 'egghead', name: 'Egghead', sagaId: 'final-saga', chapters: [1058, 1125], status: 'complete', premise: 'On an island five hundred years ahead, the world’s smartest man dies telling everyone the truth.', locationIds: ['egghead', 'thousand-sunny'], characterIds: [...CREW, 'jinbe'], overview: [
  'Egghead is Vegapunk’s laboratory, a Government research island where the future has already been built: hover-vehicles, artificial food, weapons the Marines will not receive for decades. Vegapunk himself has split his brain into six satellites, each a personality with a purpose, while his original body wanders the island as a diminutive old man. He is also a researcher of the Void Century, and the World Government has decided that what he knows outweighs what he builds.',
  'The Straw Hats arrive by accident, rescued by Vegapunk’s satellite Lilith and bringing Jewelry Bonney, a Supernova hunting the man who turned her father Kuma into a machine. CP0 arrives to kill Vegapunk, then an Admiral, then one of the Five Elders in person, then a fleet ordered to erase the island. What began as a visit becomes the most concentrated Government attack the crew has ever endured, and the first in which the enemy is not pirates but the world’s own institutions.',
  'The arc interleaves the siege with the world outside: Sabo’s revelation about the throne at Mary Geoise, Garp’s attack on Blackbeard’s island, Shanks in Elbaf, and Kuma’s long history from God Valley to a slave’s chains. At its climax Vegapunk’s recorded voice reaches every Den Den Mushi in the world with a message about the sea, and the truth stops being something only pirates and Elders know. The crew leaves with two new passengers and a debt to the giants of Elbaf.',
], beats: [
  beat('the-island-of-the-future', 'After Wano, a coast of steel', '1058–1064', [
    'The new bounties are read aboard the Sunny, and Luffy explains his dream to the crew in a whisper the reader does not hear; they laugh and cry at the same time. Elsewhere, Cross Guild, the Revolutionary commanders and Sabo make their moves, and the Kingdom of Lulusia vanishes from the map under a light from the sky. Koby, now a Marine captain and a hero, is kidnapped by Blackbeard. The Sunny drifts into a sea of ice and mechanical sharks.',
    'A woman calling herself Vegapunk drags the ship out of the cold and into Egghead, an island of glowing domes where the Straw Hats are given futuristic clothing and food that grows in a lab. Jewelry Bonney, retrieved from the same sea, reveals that she has come to kill Vegapunk for what he did to her father. Luffy, Chopper, Jinbe and Bonney are separated from the rest, and a giant robot that once tried to attack Mary Geoise sits in the centre of the island, inert for two centuries.',
  ]),
  beat('six-vegapunks', 'Punk Records and a shrunken genius', '1065–1069', [
    'Vegapunk has six satellites, named for his virtues and vices: Shaka, Lilith, Edison, Pythagoras, Atlas and York. Together with the original, they tend Punk Records, a brain the size of a dome that stores everything he has learned and that lets the seven of them share a single mind. The real Vegapunk, shrunk by his own discipline, greets Luffy’s group in the Frontier Dome and explains that he has been waiting twenty-two years for the people who would carry Ohara’s work forward.',
    'His study of the Void Century was inspired by Ohara, whose books the scholars threw into a lake as the island burned and the giants of Elbaf later carried away. Robin hears that the library she watched burn was saved, book by book, and that the old man in front of her read every one of them. Bonney, meanwhile, finds a room where Kuma’s memories are kept as a place she can walk into, and learns that her father’s past is a country she was never allowed to enter. Vegapunk asks the Straw Hats for passage off the island before his employers arrive.',
  ]),
  beat('cp0-and-the-seraphim', 'The masked visitors', '1068–1078', [
    'CP0 lands with orders to kill Vegapunk: Rob Lucci, Kaku and Stussy, bringing Seraphim, child-bodied Pacifista built from Warlords’ cells and Lunarian fire. Luffy and Lucci meet again, and the Enies Lobby fight recurs for a page with entirely different odds: the assassin who nearly killed a rookie is sent through the wall by a cartoon. The satellites cannot agree on whether to fight or surrender; Atlas is broken by Lucci and repaired by Franky, and the Seraphim, ordered by an authority nobody can find, turn on everyone.',
    'Stussy, revealed as a clone of a Rocks Pirate, betrays CP0 and bites Kaku and Lucci into paralysis. Zoro guards the two assassins with a blade at their necks. York, the satellite of greed, has been feeding the Government everything and wants to be a Celestial Dragon; she murders Shaka, the satellite of wisdom, in the room where he was about to name her, and Pythagoras is blown apart by a Seraphim. Vegapunk, seeing the island close around him, asks the Straw Hats to smuggle him and his remaining satellites out.',
  ]),
  beat('the-world-outside', 'Hachinosu, Elbaf and a truth about a throne', '1079–1089', [
    'Shanks meets Kid’s fleet at Elbaf and, with a single Divine Departure, ends the challenge and takes the Road Poneglyph copies Kid held. Garp attacks Hachinosu, Blackbeard’s pirate island, to rescue Koby with a handful of Marines and no orders, and succeeds at the cost of his own capture when Kuzan, now Blackbeard’s tenth captain, freezes his old teacher. The two Marines who taught the Straw Hats to see beyond pirates and Marines choose opposite kinds of justice.',
    'Sabo reaches Kamabakka and tells Dragon and Ivankov what happened at Mary Geoise: he saw the Empty Throne occupied, and the Five Elders kneeling to a figure who ordered the death of Nefertari Cobra. Cobra had asked about the Poneglyphs and Lili, the queen who left Mary Geoise eight hundred years earlier, and was killed for the question. Im is seen by Sabo and Cobra both, and the Five Elders are shown, in shadow, to have forms that are not human.',
  ], 'interlude'),
  beat('kizaru-descends', 'An Admiral and a Saint', '1090–1094', [
    'Admiral Kizaru arrives with a Marine armada and orders to recover Vegapunk and destroy the island’s research, and Sentomaru, who commands the Pacifista, sides with the man who raised him. Kizaru moves at the speed of light and Luffy meets him with Gear Fifth, turning the laboratory into a cartoon in which even light can be grabbed. The two exchange blows that shake the domes, and Kizaru walks through the Frontier Dome by paying for it with his own body.',
    'Then Saint Jaygarcia Saturn, one of the Five Elders, descends from the sky onto the island’s shield and steps through it. He is not a Marine and does not fight like one: he transforms into a spider-legged figure, paralyses everyone within reach, and stabs Bonney through the chest for existing. Sanji kicks him and is nearly killed for the affront. Luffy, locked with Kizaru, cannot be in two places at once, and the Elder’s shadow falls across Bonney as the story turns to her father.',
  ]),
  beat('kuma-and-bonney', 'The god of the Buccaneers', '1095–1103', [
    'Bartholomew Kuma was born a Buccaneer, a race the Government enslaved and hunted for a crime it still refuses to name. He was a child at God Valley when the Celestial Dragons hunted slaves for sport, and he escaped that night along with a girl named Ginny and a boy named Ivankov, while Rocks and Roger fought elsewhere on the island. Kuma became a pastor in the Sorbet Kingdom, then a revolutionary, and when Ginny was taken by a Celestial Dragon, he could not save her.',
    'Ginny returned dying, with a daughter. Kuma raised Bonney and watched her inherit her mother’s illness, the Sapphire Scales that turn skin to stone in sunlight. To pay for a cure he could not afford, he sold his body to Vegapunk’s Pacifista programme, agreeing to become a machine when the work was done, in exchange for Bonney’s treatment. He kept one order in the mechanism: protect the Thousand Sunny until the crew returned. The rest of him he gave away, memory by memory, until nothing remained but a slave’s chains and an instinct to reach his daughter.',
  ], 'flashback'),
  beat('the-broadcast-and-the-giant', 'A dead man speaks to the world', '1104–1116', [
    'Kuma reaches Egghead across the sea with nothing left but instinct and punches Saturn off his daughter. Saturn orders a Buster Call, and the Marines begin destroying the island regardless of who is on it. Kizaru shoots Vegapunk through the chest, and the old man’s death triggers a broadcast he prepared for it: every Den Den Mushi in the world begins playing his voice. Zoro finishes Lucci in the ruins of the labophase, and Sanji carries the Admiral’s attention long enough for Franky to carry the scientist’s body.',
    'Dorry and Brogy, the giants of Little Garden, arrive with a warship of Elbaf to repay a debt they have carried since Usopp’s crew fought beside them, and they call Luffy by the name of their sun god. Vegapunk tells the world that it is sinking, that a rise of the sea is coming, and that the Void Century holds an event the Government has hidden: a war, a kingdom, and a man who fought it. He is cut off before he finishes, but not before every ruler, pirate and Marine has heard the name Joy Boy and learned that the Government has been lying about the shape of the world.',
  ]),
  beat('the-escape', 'Two suns and an iron friend', '1117–1125', [
    'The other Elders descend in monstrous shapes, and the island falls apart under their feet and the Buster Call’s guns. Bonney, who has spent the whole arc learning that her ability can only age her into futures she truly believes, believes in the story Kuma told her about the sun god. She becomes Nika beside Luffy, and the giants of Elbaf see two Sun Gods at once, one of them a girl. Saturn tries to stop the fleeing crew with his own body and is punched aside by a father who no longer knows his name.',
    'The Iron Giant Emet wakes at last, greets Luffy as the friend it has waited two hundred years for, and releases a Haki that Joy Boy left inside it centuries earlier, halting the Elders in place. The Sunny breaks out over the Marine line by Coup de Burst, with Bonney and Kuma aboard and the satellites Lilith and Edison stowed with them, and Luffy sleeps for days. In the Holy Land, Im strips Saturn of his title for failing, and the Elder dissolves as he pleads. The crew sails with Dorry and Brogy toward Elbaf.',
  ]),
], battles: [
  battle('luffy-kizaru', 'Luffy versus Kizaru', '1092–1107', 'Keep an Admiral who moves at the speed of light away from Vegapunk while the Elder on the island takes everyone else apart.', 'Kizaru arrives before his own fleet, kicks through the Frontier Dome, and finds Luffy waiting as Nika. The laboratory becomes a cartoon: light is grabbed, floors turn to rubber, and a beam meant for Vegapunk is caught in a hand that should not exist. Kizaru fights without enthusiasm and kills Sentomaru’s loyalty and Vegapunk’s body anyway, because that is the order.', 'The Admiral is put on his back and the fight is a standstill nobody can afford, and Luffy, spent, falls asleep on the roof of the dome while Kizaru fires the shot that kills Vegapunk.', ['Light through the dome', 'A beam caught in a hand', 'The floor becomes rubber', 'An Admiral without appetite', 'A shot through the scientist']),
  battle('zoro-lucci', 'Zoro versus Rob Lucci', '1093–1110', 'Hold the assassin who nearly killed Luffy at Enies Lobby, so that the rest of the crew can move a dying scientist to the ship.', 'Lucci, freed from Stussy’s paralysis, comes for Vegapunk and finds Zoro in the way. The two circle for hours across a collapsing island, a leopard’s claws against three swords, while the Buster Call begins around them. Kaku, released to help his partner, watches the fight settle instead of joining it.', 'Zoro cuts Lucci down in the ruins and walks away with the assassin still breathing behind him. The CP0 agent who once ended Enies Lobby is now simply another man on the floor of an island the Government is burning.', ['A leopard on the labophase', 'Hours of circling', 'Kaku does not intervene', 'Three swords settle it', 'Lucci on the floor']),
  battle('siege-of-egghead', 'The Marine siege of Egghead', '1090–1122', 'Take Vegapunk alive or dead, erase what he knows, and end a witness who has just become a Sun God in front of the world.', 'Kizaru brings an armada and his own conscience, Saturn brings a body that cannot be killed and an order for a Buster Call. Luffy fights the Admiral to a standstill with Gear Fifth, Zoro finishes Lucci, and Sanji and Franky carry Vegapunk’s body. Kuma’s punch, the giants of Elbaf, Bonney’s Nika, and Emet’s stored Haki each buy minutes against an enemy that keeps adding Elders.', 'Egghead burns under the Buster Call, Vegapunk dies with his message delivered, and the Straw Hats escape with Bonney and Kuma. Saturn returns to Mary Geoise and is unmade by Im for failing.', ['Light arrives before the ships', 'A Saint steps through the dome', 'A father’s fist for an Elder', 'Every snail begins to speak', 'The giants raise their sails', 'An iron friend wakes up']),
], legacy: [
  'Vegapunk’s broadcast moves the Void Century from a secret into a public argument; every kingdom now knows the world is sinking, and the Government can no longer contain what the Poneglyphs imply. The Elders have shown their monstrous forms to witnesses, and Saturn’s fall proves that even they serve at Im’s pleasure. Bonney’s Nika and Emet’s recognition of Luffy tie the Sun God to Joy Boy in ways the story has still to explain, and the giants of Elbaf now call Luffy by a name from their own religion.',
  'Kuma is reunited with the daughter he sold himself to protect, and his memories, restored in fragments, bind the crew to the Revolutionary Army and to Ivankov. Koby’s rescue costs the Marines their greatest hero, Garp, now Blackbeard’s prisoner. Shanks holds Road Poneglyph copies, Blackbeard hunts the last, and the crew sails toward Elbaf, the giants’ homeland Usopp has dreamed of since Little Garden, with Vegapunk’s satellites Lilith and Edison aboard.',
] }),

];
